/** All translations for zizhitongjian ch.163 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第163卷卷第一百六十三", literal: "Comprehensive Mirror in Aid of Governance, Volume 163, Roll 163", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 163" },
  { zh: "【梁紀十九】　上章敦牂，一年。", literal: "[Liang Records 19] Shangzhang Dunzang; one year in all.", idiomatic: "[Liang Records 19] Shangzhang Dunzang—one year in all." },
  { zh: "太宗簡文皇帝上大寶元年（", literal: "Great Ancestor Emperor Jianwen, first year of Dabao (", idiomatic: "Emperor Jianwen of Liang, first year of Dabao (" },
  { zh: "庚午，公元五五零年）", literal: "gengwu, 550 CE)", idiomatic: "gengwu, AD 550)" },
  { zh: "春，正月，辛亥朔，大赦，改元。", literal: "In spring, the first month, on the first day xinhai, a general amnesty was proclaimed and the era name changed.", idiomatic: "In spring, the first month, on xinhai, the new moon, a general amnesty was proclaimed and the era name was changed." },
  { zh: "陳霸先發始興，至大庾嶺，蔡路養將二萬人軍於南野以拒之。", literal: "Chen Baxian set out from Shixing, reached Dayu Ridge; Cai Luyang led twenty thousand men and encamped at Nanye to resist him.", idiomatic: "Chen Baxian marched from Shixing to Dayu Ridge. Cai Luyang led twenty thousand men and encamped at Nanye to block him." },
  { zh: "路養妻侄蘭陵蕭摩訶，年十三，單騎出戰，無敢當者。", literal: "Luyang's wife's nephew Xiao Mohe of Lanling, thirteen years old, rode out alone to fight; none dared face him.", idiomatic: "Luyang's wife's nephew Xiao Mohe of Lanling was thirteen. He rode out alone to fight, and none dared face him." },
  { zh: "杜僧明馬被傷，陳霸先救之，授以所乘馬。", literal: "Du Sengming's horse was wounded; Chen Baxian rescued him and gave him the horse he rode.", idiomatic: "Du Sengming's horse was wounded. Chen Baxian pulled him clear and gave him his own mount." },
  { zh: "僧明上馬復戰，眾軍因而乘之。", literal: "Sengming mounted and fought again; the whole army pressed the advantage.", idiomatic: "Sengming remounted and fought on; the whole army swept in behind him." },
  { zh: "路養大敗，脫身走。", literal: "Luyang was routed badly and fled for his life.", idiomatic: "Luyang was routed and fled for his life." },
  { zh: "霸先進軍南康，湘東王繹承製授霸先明威將軍、交州刺史。", literal: "Baxian advanced on Nankang; Prince of Xiangdong Yi, by regent's order, made Baxian Bright Might General and Jiaozhou Inspector.", idiomatic: "Baxian advanced on Nankang. Prince Xiao Yi of Xiangdong, acting as regent, made Baxian bright might general and Jiaozhou inspector." },
  { zh: "戊辰，東魏進太原公高洋位丞相、都督中外諸軍、錄尚書事、大行台、齊郡王。", literal: "On wuchen, Eastern Wei advanced Prince of Taiyuan Gao Yang to Chancellor, Commander of All Forces Inside and Outside, Recorder of the Masters of Writing, Grand Mobile Headquarters, and Prince of Qi Commandery.", idiomatic: "On wuchen, Eastern Wei advanced Prince Gao Yang of Taiyuan to chancellor, commander of all forces inside and outside, recorder of the masters of writing, grand mobile headquarters, and prince of Qi commandery." },
  { zh: "庚午，邵陵王綸至江夏，郢州刺史南平王恪郊迎，以州讓之，綸不受；", literal: "On gengwu, Prince of Shaoling Lun reached Jiangxia; Yingzhou Inspector Prince of Nanping Ke met him in the suburbs and offered the province; Lun would not accept;", idiomatic: "On gengwu, Prince Lun of Shaoling reached Jiangxia. Yingzhou inspector Prince Ke of Nanping met him in the suburbs and offered the province; Lun refused;" },
  { zh: "乃推綸為假黃鉞，都督中外諸軍事，承製置百官。", literal: "they then made Lun acting bearer of the yellow battle-axe, Commander of All Military Affairs Inside and Outside, and by regent's order he installed the hundred offices.", idiomatic: "they then made Lun acting bearer of the yellow battle-axe, commander of all military affairs inside and outside, and by regent's order he installed the hundred offices." },
  { zh: "魏楊忠圍安陸，柳仲禮馳歸救之。", literal: "Wei Yang Zhong besieged Anlu; Liu Zhongli galloped back to rescue it.", idiomatic: "Wei general Yang Zhong besieged Anlu; Liu Zhongli galloped back to relieve it." },
  { zh: "諸將恐仲禮至則安陸難下，請急攻之。", literal: "The generals feared that if Zhongli arrived Anlu would be hard to take and asked to attack at once.", idiomatic: "The generals feared that once Zhongli arrived Anlu would be hard to take and urged an immediate assault." },
  { zh: "忠曰：「攻守勢殊，未可猝拔；", literal: "Zhong said: \"Attack and defense differ in strength; it cannot be seized in a rush;", idiomatic: "Zhong said: \"Attack and defense are not the same game; the city cannot be taken in a rush;" },
  { zh: "若引日勞師，表裡受敵，非計也。", literal: "if we draw out days and weary the army, we will be attacked inside and out—that is no plan.", idiomatic: "if we drag this out and weary the army, we will be caught between the city and relief—that is no plan at all." },
  { zh: "南人多習水軍，不閒野戰，仲禮師在近路，吾出其不意，以奇兵襲之，彼怠我奮，一舉可克。", literal: "Southerners are practiced in river warfare and unskilled in field battle; Zhongli's army is on the near road—if we take them unawares with a surprise force, they weary while we are keen, and we can take them in one stroke.", idiomatic: "Southerners train for river war, not field battle. Zhongli is close on the road. Take him unawares with a strike force—his men tired, ours eager—and we can break him at one blow." },
  { zh: "克仲禮，則安陸不攻自拔，諸城可傳檄定也。", literal: "If we overcome Zhongli, Anlu will fall without attack and the other cities can be settled by proclamation alone.", idiomatic: "Break Zhongli, and Anlu will fall without a siege; the rest of the cities can be settled by proclamation alone." },
  { zh: "」乃選騎二千，銜枚夜進，敗仲禮於崇頭，獲仲禮及其弟子禮，盡俘其眾。", literal: "\" He then chose two thousand horsemen, advanced by night with gags in their mouths, defeated Zhongli at Chongtou, captured Zhongli and his younger brother Zili, and took all his troops prisoner.", idiomatic: "\" He chose two thousand horsemen, advanced by night with gags in their mouths, routed Zhongli at Chongtou, captured Zhongli and his brother Zili, and took the whole force prisoner." },
  { zh: "馬岫以安陸，別將王叔孫以竟陵，皆降於忠。", literal: "Ma Xiu surrendered Anlu; detached general Wang Shusun surrendered Jingling; both submitted to Zhong.", idiomatic: "Ma Xiu surrendered Anlu; detached general Wang Shusun surrendered Jingling; both submitted to Yang Zhong." },
  { zh: "於是漢東之地盡入於魏。", literal: "Thus the lands east of the Han all passed into Wei.", idiomatic: "Thus the lands east of the Han all fell to Wei." },
  { zh: "廣陵人來嶷說前廣陵太守祖皓曰：「董紹先輕而無謀，人情不附。", literal: "Lai Yi of Guangling said to former Guangling Administrator Zu Hao: \"Dong Shaoxian is frivolous and without strategy; men's hearts do not cling to him.", idiomatic: "Lai Yi of Guangling said to former Guangling administrator Zu Hao: \"Dong Shaoxian is frivolous and witless; no one truly follows him." },
  { zh: "襲而殺之，此壯士之任耳。", literal: "Strike and kill him—that is a brave man's task.", idiomatic: "Strike and kill him—that is work fit for a brave man." },
  { zh: "今欲糾帥義勇，奉戴府君。", literal: "I now wish to gather righteous volunteers and install you as our lord.", idiomatic: "I mean to gather righteous volunteers and set you up as our leader." },
  { zh: "若其克捷，可立桓、文之勳；", literal: "If we succeed, we may establish merit like Huan and Wen;", idiomatic: "If we succeed, we may win merit like Duke Huan and Duke Wen of Qi;" },
  { zh: "必天未悔禍，猶足為梁室忠臣。", literal: "and even if Heaven has not yet turned from disaster, we may still suffice as loyal servants of the house of Liang.", idiomatic: "and even if Heaven has not yet turned from this disaster, we may still stand as loyal servants of Liang." },
  { zh: "」皓曰：「此僕所願也。", literal: "\" Hao said: \"That is what this servant desires.", idiomatic: "\" Hao said: \"That is what I desire." },
  { zh: "」乃相與糾合勇士，得百餘人。", literal: "\" They then together gathered brave men and got more than a hundred.", idiomatic: "\" They gathered brave men together and mustered more than a hundred." },
  { zh: "癸酉，襲廣陵，斬南兗州刺史董紹先；", literal: "On guiyou they raided Guangling and beheaded Southern Yanzhou Inspector Dong Shaoxian;", idiomatic: "On guiyou they raided Guangling and beheaded Southern Yanzhou inspector Dong Shaoxian;" },
  { zh: "據城，馳檄遠近，推前太子舍人蕭勉為刺史，仍結東魏為援。", literal: "held the city, sent proclamations flying to far and near, made former crown prince attendant Xiao Mian inspector, and at once sought Eastern Wei as ally.", idiomatic: "seized the city, sent proclamations far and wide, made former crown prince attendant Xiao Mian inspector, and at once sought Eastern Wei as ally." },
  { zh: "皓，□恆之之子；", literal: "Hao was the son of □ Hengzhi;", idiomatic: "Hao was the son of □ Hengzhi;" },
  { zh: "勉，勃之兄也。", literal: "Mian was Bo's elder brother.", idiomatic: "Mian was the elder brother of Xiao Bo." },
  { zh: "乙亥，景遣郭元建帥眾奄至，皓嬰城固守。", literal: "On yihai, Jing sent Guo Yuanjian leading troops in a sudden arrival; Hao closed the city and held firm.", idiomatic: "On yihai, Hou Jing sent Guo Yuanjian with troops in a sudden strike; Hao shut the gates and held firm." },
  { zh: "二月，魏楊忠乘勝至石城，欲進逼江陵，湘東王繹遣舍人庾恪說忠曰：「察來伐叔而魏助之，何以使天下歸心！", literal: "In the second month, Wei Yang Zhong pressed his victory to Shicheng and wished to advance on Jiangling; Prince of Xiangdong Yi sent Gentleman-Attendant Yu Ke to persuade Zhong, saying: \"Liang came to punish its uncle-rebel while Wei aids him—how will the empire turn its hearts to you!", idiomatic: "In the second month, Yang Zhong of Wei pressed his victory to Shicheng and meant to advance on Jiangling. Prince Xiao Yi of Xiangdong sent gentleman-attendant Yu Ke to persuade him: \"Liang marched to punish a rebel uncle while Wei aids him—how will the empire ever turn its hearts to you!" },
  { zh: "」忠遂停湕北。", literal: "\" Zhong then halted north of the Jian.", idiomatic: "\" Yang Zhong then halted north of the Jian." },
  { zh: "繹遣舍人王孝祀等送子方略為質以求和，魏人許之。", literal: "Yi sent Gentleman-Attendant Wang Xiaosi and others to deliver his son Fanglue as hostage to seek peace; the Wei men agreed.", idiomatic: "Yi sent gentleman-attendant Wang Xiaosi and others with his son Fanglue as hostage to sue for peace; Wei agreed." },
  { zh: "繹與忠盟曰：「魏以石城為封，梁以安陸為界，請同附庸，並送質子，貿遷有無，永敦鄰睦。", literal: "Yi swore alliance with Zhong, saying: \"Wei takes Shicheng as its fief, Liang takes Anlu as its border; let us both be vassal states, each send a hostage son, trade what we have and lack, and forever keep neighborly peace.", idiomatic: "Yi swore alliance with Yang Zhong: \"Wei shall hold Shicheng as fief, Liang shall hold Anlu as border; let us both stand as vassal states, each send a hostage son, trade what we have and lack, and keep neighborly peace forever." },
  { zh: "」忠乃還。", literal: "\" Zhong then withdrew.", idiomatic: "\" Yang Zhong then withdrew." },
  { zh: "宕昌王梁彌定為其宗人獠甘所襲，彌定奔魏，獠甘自立。", literal: "Prince of Dangchang Liang Miding was attacked by his clansman Liao Gan; Miding fled to Wei and Liao Gan set himself up as ruler.", idiomatic: "Prince Liang Miding of Dangchang was attacked by his clansman Liao Gan; Miding fled to Wei and Liao Gan declared himself ruler." },
  { zh: "羌酋傍乞鐵□據渠株川，與渭州民鄭五丑合諸羌以叛魏。", literal: "Qiang chieftain Pangqi Tiex□ held Qizhu River valley and, with Zheng Wuchou of Weizhou and the various Qiang, rebelled against Wei.", idiomatic: "Qiang chieftain Pangqi Tiex□ held the Qizhu River valley and, with Zheng Wuchou of Weizhou and the Qiang tribes, rebelled against Wei." },
  { zh: "丞相泰使大將軍宇文貴、涼州刺史史寧討之，擒斬鐵□、五丑。", literal: "Chancellor Tai sent Grand General Yuwen Gui and Liangzhou Inspector Shi Ning to campaign against them and captured and beheaded Tiex□ and Wuchou.", idiomatic: "Chancellor Yuwen Tai sent grand general Yuwen Gui and Liangzhou inspector Shi Ning against them and captured and beheaded Tiex□ and Wuchou." },
  { zh: "寧別擊獠甘，破之，獠甘將百騎奔生羌鞏廉玉。", literal: "Ning separately attacked Liao Gan, defeated him; Liao Gan led a hundred horsemen in flight to the raw Qiang Gong Lianyu.", idiomatic: "Ning separately attacked Liao Gan and broke him. Liao Gan fled with a hundred riders to the raw Qiang chieftain Gong Lianyu." },
  { zh: "寧復納彌定於宕昌，置岷州於渠株川，進擊鞏廉玉，斬獠甘，虜廉玉送長安。", literal: "Ning again installed Miding in Dangchang, established Min province at Qizhu River valley, advanced to attack Gong Lianyu, beheaded Liao Gan, captured Lianyu, and sent him to Chang'an.", idiomatic: "Ning restored Miding in Dangchang, established Min province on the Qizhu River, advanced on Gong Lianyu, beheaded Liao Gan, captured Lianyu, and sent him to Chang'an." },
  { zh: "侯景遣任約、於慶等帥眾二萬攻諸籓。", literal: "Hou Jing sent Ren Yue, Yu Qing, and others leading twenty thousand men to attack the various princely domains.", idiomatic: "Hou Jing sent Ren Yue, Yu Qing, and others with twenty thousand men to attack the princely domains." },
  { zh: "邵陵王綸欲救河東王譽，而兵糧不足，乃致書於湘東王繹曰：「天時地利，不及人和，況乎手足肱支，豈可相害！", literal: "Prince of Shaoling Lun wished to rescue Prince of Hedong Yu but lacked troops and grain; he sent a letter to Prince of Xiangdong Yi, saying: \"Heaven's season and earth's advantage are less than human harmony—how much more so for arms and legs of one body: how can they harm one another!", idiomatic: "Prince Lun of Shaoling wished to rescue Prince Yu of Hedong but lacked troops and grain. He wrote Prince Xiao Yi of Xiangdong: \"Heaven's season and earth's advantage mean less than human harmony—how much less may the arms and legs of one body tear at each other!" },
  { zh: "今社稷危恥，創巨痛深，唯應剖心嘗膽，泣血枕戈，其餘小忿，或宜容貰。", literal: "Now the altars are in peril and shame; the wound is vast and the pain deep—we should only split our hearts and taste gall, weep blood and sleep on spears; other small resentments may sometimes be borne.", idiomatic: "The altars stand in peril and shame; the wound is vast and the pain runs deep. We should split our hearts and taste gall, weep blood and sleep on our spears. Other small resentments may sometimes be set aside." },
  { zh: "若外難未除，家禍仍構，料今訪古，未或不亡。", literal: "If outer peril is not removed and inner calamity still builds, I reckon that from today back through antiquity, none have failed to perish.", idiomatic: "If outer enemies remain and kin still turn on kin, I reckon that from today back through antiquity, none have failed to perish." },
  { zh: "夫征戰之理，唯求克勝；", literal: "In the logic of war, one seeks only victory;", idiomatic: "In war one seeks only victory;" },
  { zh: "至於骨肉之戰，愈勝愈酷，捷則非功，敗則有喪，勞兵損義，虧失多矣。", literal: "but in kin fighting, the more one wins the crueller it grows—triumph brings no merit, defeat brings mourning, troops are worn and righteousness harmed, and losses are many.", idiomatic: "but in war between kin, the more you win the crueller it grows. Triumph brings no merit, defeat brings mourning; troops are worn down, righteousness is harmed, and the losses mount." },
  { zh: "侯景之軍所以未窺江外者，良為籓屏盤固，宗鎮強密。", literal: "The reason Hou Jing's army has not yet peered beyond the river is precisely that the princely screens are firm and the clan garrisons strong and close.", idiomatic: "Hou Jing's army has not yet peered beyond the river precisely because the princely screens stand firm and the clan garrisons are strong and close." },
  { zh: "弟若陷洞庭，不戢兵刃，雍州疑迫，何以自安，必引進魏軍以求形援。", literal: "If younger brother takes Dongting and does not sheathe blades, Yong province will be pressed with doubt—how will you keep yourself safe? You will surely bring in Wei troops to seek visible aid.", idiomatic: "If you take Dongting and do not sheathe your blades, Yong province will be pressed with doubt—how will you keep yourself safe? You will surely bring in Wei troops to seek visible aid." },
  { zh: "弟若不安，家國去矣。", literal: "If younger brother is not secure, house and state are gone.", idiomatic: "If you are not secure, house and state are gone." },
  { zh: "必希解湘州之圍，存社稷之計。", literal: "I earnestly hope you will lift the siege of Xiang province and preserve the plan for the altars.", idiomatic: "I earnestly beg you to lift the siege of Xiang province and preserve the altars." },
  { zh: "」繹復書，陳譽過惡不赦，且曰：「察引楊忠來相侵逼，頗遵談笑，用卻秦軍，曲直有在，不復自陳。", literal: "\" Yi replied, setting forth Yu's crimes as beyond pardon, and said: \"Cha brought Yang Zhong to invade and press us; I followed the talk and laughter and sent the Qin army back—right and wrong are clear; I need not argue further.", idiomatic: "\" Xiao Yi replied, listing Yu's crimes as beyond pardon, and wrote: \"You brought Yang Zhong to invade and press us. I followed the talk and sent the Qin army back—right and wrong are clear; I need not argue further." },
  { zh: "臨湘旦平，暮便即路。", literal: "Linxiang will fall by morning; by evening I shall be on the road.", idiomatic: "Linxiang will fall by morning; by evening I shall be on the road." },
  { zh: "」綸得書，投之於案，慷慨流涕曰「天下之事，一至於斯！", literal: "\" Lun received the letter, cast it on the table, and with generous emotion wept, saying, \"Affairs under Heaven have come to this!\"", idiomatic: "\" Lun read the letter, threw it on the table, and wept: \"Affairs under Heaven have come to this!\"" },
  { zh: "湘州若敗，吾亡無日矣！", literal: "If Xiang province falls, my destruction is not far off!", idiomatic: "If Xiang province falls, my days are numbered!" },
  { zh: "侯景遣侯子鑒帥舟師八千，自帥徒兵一萬，攻廣陵，三日，克之，執祖皓，縛而射之，箭遍體，然後車裂以徇；", literal: "Hou Jing sent Hou Zijian leading eight thousand river troops; he himself led ten thousand foot soldiers to attack Guangling; in three days it fell; he seized Zu Hao, bound him and shot him until arrows covered his body, then quartered him by chariot as warning;", idiomatic: "Hou Jing sent Hou Zijian with eight thousand river troops and himself led ten thousand foot soldiers against Guangling. In three days the city fell. He seized Zu Hao, bound him, shot him until arrows covered his body, then quartered him by chariot as warning;" },
  { zh: "城中無少長皆埋之於地，馳馬射而殺之。", literal: "within the city none young or old—all were buried in the earth, and horsemen galloped over them shooting and killing them.", idiomatic: "within the city none young or old were spared—they were buried in pits and horsemen galloped over them, shooting them down." },
  { zh: "以子鑒為南兗州刺史，鎮廣陵。", literal: "He made Zijian Southern Yanzhou Inspector, garrisoning Guangling.", idiomatic: "He made Zijian Southern Yanzhou inspector and garrisoned him at Guangling." },
  { zh: "景還建康。", literal: "Jing returned to Jiankang.", idiomatic: "Hou Jing returned to Jiankang." },
  { zh: "丙戌，以安陸王大春為東揚州刺史。", literal: "On bingxu, Prince Dachun of Anlu was made Eastern Yangzhou Inspector.", idiomatic: "On bingxu, Prince Dachun of Anlu was made Eastern Yangzhou inspector." },
  { zh: "省吳州。", literal: "Wu province was abolished.", idiomatic: "Wu province was abolished." },
  { zh: "乙巳，以尚書僕射王克為左僕射。", literal: "On yisi, Vice Minister of the Masters of Writing Wang Ke was made Left Vice Minister.", idiomatic: "On yisi, vice minister of the masters of writing Wang Ke was made left vice minister." },
  { zh: "庚寅，東魏以尚書令高隆之為太保。", literal: "On gengyin, Eastern Wei made Minister of the Masters of Writing Gao Longzhi Grand Guardian.", idiomatic: "On gengyin, Eastern Wei made minister of the masters of writing Gao Longzhi grand guardian." },
  { zh: "宣城內史楊白華進據安吳，侯景遣於子悅等帥眾攻之，不克。", literal: "Xuancheng Interior Secretary Yang Baihua advanced and held Anwu; Hou Jing sent Yu Ziyue and others leading troops to attack but could not take it.", idiomatic: "Xuancheng interior secretary Yang Baihua advanced and held Anwu. Hou Jing sent Yu Ziyue and others against him but could not take it." },
  { zh: "東魏行台辛術將兵入寇，圍陽平，不克。", literal: "Eastern Wei Mobile Headquarters Xin Shu led troops in invasion, besieged Yangping, and could not take it.", idiomatic: "Eastern Wei mobile headquarters commander Xin Shu invaded, besieged Yangping, and could not take it." },
  { zh: "侯景納上女溧陽公主，甚愛之。", literal: "Hou Jing took the emperor's daughter, Princess of Liyang, in marriage and loved her greatly.", idiomatic: "Hou Jing married the emperor's daughter, the Princess of Liyang, and doted on her." },
  { zh: "三月，甲申，景請上禊宴於樂游苑，帳飲三日。", literal: "In the third month, on jiashen, Jing asked the emperor to a spring purification feast in Leyou Garden; they drank under tents for three days.", idiomatic: "In the third month, on jiashen, Hou Jing invited the emperor to a spring purification feast in Leyou Garden; they drank under tents for three days." },
  { zh: "上還宮，景與公主共據御床，南面並坐，群臣文武列坐侍宴。", literal: "When the emperor returned to the palace, Jing and the princess together occupied the imperial couch, sat facing south side by side, and civil and military officials arrayed themselves in seats to attend the feast.", idiomatic: "When the emperor returned to the palace, Hou Jing and the princess shared the imperial couch, sat facing south side by side, while civil and military officials arrayed themselves to attend the feast." },
  { zh: "庚申，東魏進丞相洋爵為齊王。", literal: "On gengshen, Eastern Wei advanced Chancellor Yang's rank to Prince of Qi.", idiomatic: "On gengshen, Eastern Wei advanced Chancellor Gao Yang's rank to prince of Qi." },
  { zh: "臨川內史始興王毅等擊莊鐵，鄱陽王范遣其將巴西侯瑱救之，毅等敗死。", literal: "Linchuan Interior Secretary Prince Yi of Shixing and others attacked Zhuang Tie; Prince of Poyang Fan sent his general Hou Zhen of Baxi to rescue him; Yi and the rest were defeated and died.", idiomatic: "Linchuan interior secretary Prince Yi of Shixing and others attacked Zhuang Tie. Prince Fan of Poyang sent his general Hou Zhen of Baxi to rescue him. Yi and the rest were defeated and killed." },
  { zh: "鄱陽世子嗣與任約戰於三章，約敗走；", literal: "Poyang Heir Si fought Ren Yue at Sanzhang; Yue was defeated and fled;", idiomatic: "Poyang heir Si fought Ren Yue at Sanzhang. Yue was beaten and fled;" },
  { zh: "嗣因徙鎮三章，謂之安樂柵。", literal: "Si then moved his garrison to Sanzhang and called it Anle Palisade.", idiomatic: "Si then moved his camp to Sanzhang and called it Anle Palisade." },
  { zh: "夏，四月，庚辰朔，湘東王繹以上甲侯韶為長沙王。", literal: "In summer, the fourth month, on the first day gengchen, Prince of Xiangdong Yi made Senior Armorer Hou Shao Prince of Changsha.", idiomatic: "In summer, the fourth month, on gengchen, the new moon, Prince Xiao Yi of Xiangdong made senior armorer Hou Shao prince of Changsha." },
  { zh: "丙午，侯景請上幸西州，上御素輦，侍衛四百餘人，景浴鐵數千，翼衛左右。", literal: "On bingwu, Hou Jing asked the emperor to visit Xizhou; the emperor rode a plain carriage with more than four hundred guards; Jing had several thousand armored men flanking left and right.", idiomatic: "On bingwu, Hou Jing asked the emperor to visit Xizhou. The emperor rode a plain carriage with more than four hundred guards; Hou Jing had several thousand armored men flanking him left and right." },
  { zh: "上聞絲竹，淒然泣下，命景起舞，景亦請上起舞。", literal: "The emperor heard silk and bamboo music and wept desolately; he ordered Jing to dance, and Jing also asked the emperor to dance.", idiomatic: "The emperor heard music and wept. He ordered Hou Jing to dance; Hou Jing asked the emperor to dance as well." },
  { zh: "酒闌坐散，上抱景於床曰：「我念丞相！", literal: "When the wine was spent and the seats dispersed, the emperor embraced Jing on the couch and said: \"I miss the Chancellor!", idiomatic: "When the wine was spent and the guests dispersed, the emperor embraced Hou Jing on the couch and said: \"I miss the Chancellor!" },
  { zh: "」景曰：「陛下如不念臣，臣何得至此！", literal: "\" Jing said: \"If Your Majesty did not miss your servant, how could your servant have come to this!", idiomatic: "\" Hou Jing said: \"If Your Majesty did not miss me, how could I have come to this!" },
  { zh: "」逮夜乃罷。", literal: "\" Only at night did it end.", idiomatic: "\" Only at night did it end." },
  { zh: "時江南連年旱蝗，江、揚尤甚，百姓流亡，相與入山谷、江湖，采草根、木葉、菱芡而食之，所在皆盡，死者蔽野。", literal: "At this time the south of the Yang had drought and locusts for years in succession; Jiang and Yang suffered especially; common people fled, entering together into valleys and rivers and lakes to gather grass roots, tree leaves, water chestnuts and gorgon seeds to eat; wherever they went all was exhausted and the dead covered the wild.", idiomatic: "The south of the Yang had suffered drought and locusts for years; Jiang and Yang were worst hit. People fled into valleys and along rivers and lakes, eating grass roots, leaves, water chestnuts, and gorgon seeds until nothing remained; the dead covered the countryside." },
  { zh: "富室無食，皆鳥面鵠形，衣羅綺，懷金玉，俯伏床帷，待命聽終。", literal: "Rich houses had no food; all were bird-faced and swan-bodied, dressed in gauze and silk, carrying gold and jade, lying prostrate by bed curtains awaiting the end.", idiomatic: "Even rich households went hungry. Men were gaunt as birds and storks, still dressed in gauze and silk, gold and jade at their belts, lying by their bed curtains waiting for death." },
  { zh: "千里絕煙，人跡罕見，白骨成聚，如丘隴焉。", literal: "For a thousand li smoke was gone and human tracks rarely seen; white bones heaped like mounds and hillocks.", idiomatic: "For a thousand li no smoke rose and human tracks were rare; white bones lay heaped like hills." },
  { zh: "景性殘酷，於石頭立大碓，有犯法者搗殺之。", literal: "Jing's nature was cruel; at Shitou he set up a great pestle and killed lawbreakers by pounding.", idiomatic: "Hou Jing was cruel by nature. At Shitou he set up a great pestle and killed lawbreakers by pounding them to death." },
  { zh: "常戒諸將曰：「破柵平城，當淨殺之，使天下知吾威名。", literal: "He often warned his generals: \"When you break palisades and level cities, you should kill them clean, so all under Heaven knows my dread name.", idiomatic: "He often warned his generals: \"When you break palisades and level cities, kill them clean, so all under Heaven knows my dread name." },
  { zh: "」故諸將每戰勝，專以焚掠為事，斬刈人如草芥，以資戲笑。", literal: "\" Therefore whenever his generals won battle they devoted themselves to burning and plunder, cutting men like grass for sport and laughter.", idiomatic: "\" So whenever his generals won they devoted themselves to burning and plunder, cutting men like grass for sport and laughter." },
  { zh: "由是百姓雖死，終不附之。", literal: "Because of this, though the common people died, in the end they would not attach to him.", idiomatic: "Because of this, though the people died in masses, in the end they would not follow him." },
  { zh: "又禁人偶語，犯者刑及外族。", literal: "He also forbade people to speak in pairs; offenders' punishment reached their outer kin.", idiomatic: "He also forbade people to speak in pairs; offenders' kin were punished as well." },
  { zh: "為其將帥者，悉稱行台，來降附者，悉稱開府，其親寄隆重者曰左右廂公，勇力兼人者曰庫直都督。", literal: "Those who were his generals all called themselves Mobile Headquarters; those who came to submit all called themselves Independent Staff; those he trusted most heavily were called Left and Right Wing Lords; those whose courage and strength matched many men were called Armory Direct Commanders.", idiomatic: "His generals all called themselves mobile headquarters; those who submitted called themselves independent staff; those he trusted most were left and right wing lords; men of matchless strength were armory direct commanders." },
  { zh: "魏封皇子儒為燕王，公為吳王。", literal: "Wei enfeoffed the imperial prince Ru as Prince of Yan and Gong as Prince of Wu.", idiomatic: "Wei enfeoffed imperial prince Ru as prince of Yan and Gong as prince of Wu." },
  { zh: "侯景召宋子仙還京口。", literal: "Hou Jing summoned Song Zixian back to Jingkou.", idiomatic: "Hou Jing summoned Song Zixian back to Jingkou." },
  { zh: "邵陵王綸在郢州，以聽事為正陽殿，內外齋閣，悉加題署。", literal: "Prince of Shaoling Lun was at Ying province; he made the audience hall into Zhengyang Palace and labeled all inner and outer fasting pavilions.", idiomatic: "Prince Lun of Shaoling was at Ying province. He turned the audience hall into Zhengyang Palace and labeled every inner and outer fasting pavilion." },
  { zh: "其部下陵暴軍府，郢州將佐莫不怨之。", literal: "His subordinates bullied the army headquarters; Ying province officers none but resented it.", idiomatic: "His men bullied the army headquarters; every officer in Ying province resented it." },
  { zh: "咨議參軍江仲舉，南平王恪之謀主也，說恪圖綸，恪驚曰：「若我殺邵陵，寧靜一鎮，荊、益兄弟必皆內喜，海內若平，則以大義責我矣。", literal: "Advisory Staff Officer Jiang Zhongju, chief strategist of Prince of Nanping Ke, urged Ke to plot against Lun; Ke in alarm said: \"If I kill the Prince of Shaoling, I may quiet one province, but the brothers of Jing and Yi will all rejoice inwardly; if the realm is pacified, they will rebuke me with righteousness.", idiomatic: "Advisory staff officer Jiang Zhongju, chief strategist of Prince Ke of Nanping, urged Ke to plot against Lun. Ke said in alarm: \"If I kill the Prince of Shaoling I may quiet one province, but the princes of Jing and Yi will rejoice inwardly; if the realm is pacified they will rebuke me in the name of righteousness." },
  { zh: "且巨逆未梟，骨肉相殘，自亡之道也。", literal: "Moreover the great rebel is not yet slain—kin slaughtering kin is the road to self-destruction.", idiomatic: "Moreover the great rebel is not yet slain—kin slaughtering kin is the road to ruin." },
  { zh: "卿且息之。", literal: "Sir, cease this for now.", idiomatic: "Stop this for now." },
  { zh: "」仲舉不從，部分諸將，刻日將發；", literal: "\" Zhongju would not follow; he assigned the generals and set a day to launch;", idiomatic: "\" Zhongju would not listen. He assigned the generals and set a day to strike;" },
  { zh: "謀洩，綸壓殺之。", literal: "the plot leaked and Lun crushed and killed him.", idiomatic: "the plot leaked and Lun crushed and killed him." },
  { zh: "恪狼狽往謝，綸曰：「群小所作，非由兄也。", literal: "Ke in distress went to apologize; Lun said: \"Petty men did this—not through elder brother's doing.", idiomatic: "Ke went in distress to apologize. Lun said: \"Petty men did this—not through your doing, elder brother." },
  { zh: "凶黨已斃，兄勿深憂。", literal: "The evil faction is already dead; elder brother, do not grieve deeply.", idiomatic: "The plotters are dead. Do not grieve, elder brother." },
  { zh: "王僧辯急攻長沙，辛巳，克之。", literal: "Wang Senbian pressed the attack on Changsha urgently; on xinsi, he took it.", idiomatic: "Wang Senbian pressed the attack on Changsha. On xinsi he took it." },
  { zh: "執河東王譽，斬之，傳首江陵，湘東王繹反其首而葬之。", literal: "He seized Prince of Hedong Yu, beheaded him, sent the head to Jiangling; Prince of Xiangdong Yi returned the head and buried it.", idiomatic: "He seized Prince Yu of Hedong, beheaded him, and sent the head to Jiangling. Prince Xiao Yi of Xiangdong returned the head and buried it." },
  { zh: "初，世子方等之死，臨蒸周鐵虎功最多，譽委遇甚重。", literal: "Earlier, at Heir Fangdeng's death, Zhou Tiehu of Linzheng had done the most merit; Yu entrusted and favored him greatly.", idiomatic: "Earlier, when heir Fangdeng died, Zhou Tiehu of Linzheng had done the most. Yu trusted and favored him greatly." },
  { zh: "僧辯得鐵虎，命烹之，呼曰：「侯景未滅，奈何殺壯士！", literal: "Senbian captured Tiehu and ordered him boiled; Tiehu cried: \"Hou Jing is not yet destroyed—how can you kill a brave man!", idiomatic: "Senbian captured Tiehu and ordered him boiled. Tiehu cried: \"Hou Jing is not yet destroyed—how can you kill a brave man!" },
  { zh: "」僧辯奇其言而釋之，還其麾下。", literal: "\" Senbian marveled at his words and released him, returning him to his command.", idiomatic: "\" Senbian marveled at his words, released him, and returned him to his command." },
  { zh: "繹以僧辯為左衛將軍，加侍中、鎮西長史。", literal: "Yi made Senbian Left Guard General, added Palace Attendant and Western Garrison Chief Clerk.", idiomatic: "Yi made Senbian left guard general, added palace attendant and western garrison chief clerk." },
  { zh: "繹自去歲聞高祖之喪，以長沙未下，故匿之。", literal: "Yi himself, since last year when he heard of Gaozu's death, because Changsha had not fallen, therefore concealed it.", idiomatic: "Yi himself, since learning of Emperor Wu's death the year before, had concealed the news because Changsha had not yet fallen." },
  { zh: "壬寅，始發喪，刻檀為高祖像，置於百福殿，事之甚謹，動靜必咨焉。", literal: "On renyin he at last announced the mourning, carved an image of Gaozu in sandalwood, placed it in Baifu Hall, served it with great reverence, and in movement or rest always consulted it.", idiomatic: "On renyin he at last announced the mourning, carved a sandalwood image of Emperor Wu, placed it in Baifu Hall, and served it with such reverence that in every move he consulted it." },
  { zh: "繹以為天子制於賊臣，不肯從大寶之號，猶稱太清四年。", literal: "Yi held that the Son of Heaven was controlled by rebel ministers and would not follow the Dabao era name, still calling it the fourth year of Taiqing.", idiomatic: "Yi held that the Son of Heaven was controlled by rebel ministers and would not adopt the Dabao era name, still calling it the fourth year of Taiqing." },
  { zh: "丙午，繹下令大舉討侯景，移檄遠近。", literal: "On bingwu, Yi ordered a great campaign against Hou Jing and sent proclamations to far and near.", idiomatic: "On bingwu, Yi ordered a great campaign against Hou Jing and sent proclamations far and near." },
  { zh: "鄱陽王范至湓城，以晉熙為晉州，遣其世子嗣為刺史，江州郡縣多輒改易。", literal: "Prince of Poyang Fan reached Pencheng, made Jinxi into Jin province, sent his heir Si as inspector; many Jiangzhou commanderies and counties were changed at will.", idiomatic: "Prince Fan of Poyang reached Pencheng, made Jinxi into Jin province, and sent his heir Si as inspector; many Jiangzhou counties were changed at will." },
  { zh: "尋陽王大心，政令所行，不出一郡。", literal: "Prince Daxin of Xunyang—his government's orders reached no farther than one commandery.", idiomatic: "Prince Daxin of Xunyang—his orders reached no farther than one commandery." },
  { zh: "大心遣兵擊莊鐵，嗣與鐵素善，請發兵救之，范遣侯瑱帥精甲五千助鐵。", literal: "Daxin sent troops against Zhuang Tie; Si and Tie had long been friendly and asked that troops be sent to rescue; Fan sent Hou Zhen leading five thousand elite armored men to aid Tie.", idiomatic: "Daxin sent troops against Zhuang Tie. Si and Tie had long been friends and asked for rescue; Fan sent Hou Zhen with five thousand elite armored men to aid Tie." },
  { zh: "由是二鎮互相猜忌，無復討賊之志。", literal: "Because of this the two garrisons mutually suspected one another and had no further will to campaign against the bandits.", idiomatic: "From this the two garrisons grew mutually suspicious and lost all will to fight the rebels." },
  { zh: "大心使徐嗣徽帥眾二千，築壘稽亭以備范，市糴不通，范數萬之眾，無所得食，多餓死。", literal: "Daxin had Xu Sihui lead two thousand men to build a fort at Jiting to guard against Fan; market grain could not pass; Fan's force of tens of thousands got no food and many starved.", idiomatic: "Daxin had Xu Sihui lead two thousand men to build a fort at Jiting against Fan. Grain could not reach the markets; Fan's army of tens of thousands found no food and many starved." },
  { zh: "范憤恚，疽發於背，五月，乙卯，卒。", literal: "Fan, angry and resentful, had a carbuncle break out on his back; in the fifth month, on yimao, he died.", idiomatic: "Fan, furious and resentful, developed a carbuncle on his back. In the fifth month, on yimao, he died." },
  { zh: "其眾秘不發喪，奉范弟安南侯恬為主，有眾數千人。", literal: "His troops secretly did not announce the mourning and made Fan's younger brother Marquis Tian of Annan their leader, with several thousand men.", idiomatic: "His troops kept the death secret and made Fan's younger brother Marquis Tian of Annan their leader, with several thousand men." },
  { zh: "丙辰，侯景以元思虔為東道大行台，鎮錢塘。", literal: "On bingchen, Hou Jing made Yuan Siqian Eastern Route Grand Mobile Headquarters, garrisoning Qiantang.", idiomatic: "On bingchen, Hou Jing made Yuan Siqian eastern route grand mobile headquarters and garrisoned him at Qiantang." },
  { zh: "丁巳，以侯子鑒為南兗州刺史。", literal: "On dingsi, he made Hou Zijian Southern Yanzhou Inspector.", idiomatic: "On dingsi, he made Hou Zijian Southern Yanzhou inspector." },
  { zh: "東魏齊王洋之為開府也，勃海高德政為管記，由是親暱，言無不盡。", literal: "When Eastern Wei's Prince of Qi Yang was made Independent Staff, Gao Dezheng of Bohai was his chief clerk; from this they were intimate and spoke without reserve.", idiomatic: "When Gao Yang, prince of Qi in Eastern Wei, opened an independent staff, Gao Dezheng of Bohai was his chief clerk; from this they were intimate and spoke without reserve." },
  { zh: "金紫光祿大夫丹楊徐之才、北平太守廣宗宋景業，皆善圖讖，以為太歲在午，當有革命，因德政以白洋，勸之受禪。", literal: "Grand Master of Splendid Brightness Xu Zhicai of Danyang and Beiping Administrator Song Jingye of Guangzong were both skilled in prognostic texts and held that with the Grand Year in wu there must be revolution; through Dezheng they informed Yang and urged him to accept the abdication.", idiomatic: "Grand master of splendid brightness Xu Zhicai of Danyang and Beiping administrator Song Jingye of Guangzong were both skilled in prognostic texts. They held that with the Grand Year in wu there must be revolution; through Dezheng they told Yang and urged him to accept the throne." },
  { zh: "洋以告婁太妃，太妃曰：「汝父如龍，兄如虎，猶以天位不可妄據，終身北面。", literal: "Yang told Grand Consort Lou; the Grand Consort said: \"Your father was like a dragon, your elder brother like a tiger, yet they still held that Heaven's throne must not be seized rashly and faced north all their lives.", idiomatic: "Yang told Grand Consort Lou. She said: \"Your father was like a dragon, your brother like a tiger, yet they held that Heaven's throne must not be seized rashly and faced north all their lives." },
  { zh: "汝獨何人，欲行舜、禹之事乎！", literal: "Who are you alone, that you wish to do what Shun and Yu did!", idiomatic: "Who are you, that you wish to do what Shun and Yu did!" },
  { zh: "」洋以告之才，之才曰：「正為不及父兄，故宜早升尊位耳。", literal: "\" Yang told Zhicai; Zhicai said: \"It is precisely because you do not match father and elder brother that you should early ascend the honored throne.", idiomatic: "\" Yang told Zhicai. Zhicai said: \"It is precisely because you do not match your father and brother that you should ascend the throne early." },
  { zh: "」洋鑄像卜之而成，乃使開府儀同三司段韶問肆州刺史斛律金，金來見洋，固言不可，以宋景業首陳符命，請殺之。", literal: "\" Yang cast an image and divined; it succeeded; he then sent Equal in Honor to the Three Dukes Duan Shao to ask Sizhou Inspector Hulu Jin; Jin came to see Yang and firmly said it could not be done; he cited Song Jingye as first to proclaim the mandate and asked to kill him.", idiomatic: "\" Yang cast an image and divined successfully. He sent equal in honor to the three dukes Duan Shao to ask Sizhou inspector Hulu Jin. Jin came, firmly opposed the plan, named Song Jingye as first to proclaim the mandate, and asked to kill him." },
  { zh: "洋與諸貴議於太妃前，太妃曰：「吾兒懦直，必無此心，高德政樂禍，教之耳。", literal: "Yang discussed with the nobles before the Grand Consort; the Grand Consort said: \"My son is timid and straight; he surely has no such heart—Gao Dezheng delights in disaster and taught him.", idiomatic: "Yang discussed with the nobles before the Grand Consort. She said: \"My son is timid and straight; he surely has no such heart. Gao Dezheng delights in disaster and taught him." },
  { zh: "」洋以人心不壹，使高德政如鄴察公卿之意，未還；", literal: "\" Yang, because men's hearts were not united, sent Gao Dezheng to Ye to observe the intent of the dukes and ministers; he had not returned;", idiomatic: "\" Because hearts were not united, Yang sent Gao Dezheng to Ye to sound out the dukes and ministers. He had not returned;" },
  { zh: "洋擁兵而東，至平都城，召諸勳貴議之，莫敢對。", literal: "Yang led troops east, reached Pingdu city, summoned the meritorious nobles to discuss it, and none dared answer.", idiomatic: "Yang led troops east to Pingdu city, summoned the meritorious nobles to discuss it, and none dared answer." },
  { zh: "長史杜弼曰：「關西，國之勁敵，若受魏禪，恐彼挾天子，自稱義兵而東向，王何以待之！", literal: "Chief Clerk Du Bi said: \"Guanxi is the state's fierce enemy; if you accept Wei's abdication, I fear they will hold the Son of Heaven and call themselves a righteous army marching east—how will my lord meet them!", idiomatic: "Chief clerk Du Bi said: \"Guanxi is the state's fierce enemy. If you accept Wei's abdication, I fear they will hold the Son of Heaven, call themselves a righteous army, and march east—how will you meet them!" },
  { zh: "」徐之才曰：「今與王爭天下者，彼亦欲為王所為。", literal: "\" Xu Zhicai said: \"Those who contend with my lord for the realm today also wish to do what my lord does.", idiomatic: "\" Xu Zhicai said: \"Those who contend with you for the realm today also wish to do what you do." },
  { zh: "縱其屈強，不過隨我稱帝耳。", literal: "Even if they are stubborn and strong, at most they will follow us in calling themselves emperor.", idiomatic: "Even if they are stubborn, at most they will follow us in calling themselves emperor." },
  { zh: "」弼無以應。", literal: "\" Bi had nothing to answer.", idiomatic: "\" Bi had nothing to answer." },
  { zh: "高德政至鄴，諷公卿，莫有應者。", literal: "Gao Dezheng reached Ye and hinted to the dukes and ministers; none responded.", idiomatic: "Gao Dezheng reached Ye and sounded out the dukes and ministers; none responded." },
  { zh: "司馬子如逆洋於遼陽，固言未可。", literal: "Sima Ziru met Yang at Liaoyang and firmly said it could not yet be done.", idiomatic: "Sima Ziru met Yang at Liaoyang and firmly said it could not yet be done." },
  { zh: "洋欲還，倉丞李集曰：「王來為何事，而今欲還？", literal: "Yang wished to return; warehouse clerk Li Ji said: \"My lord came for what affair, and now wishes to return?", idiomatic: "Yang wished to return. Warehouse clerk Li Ji said: \"My lord came for what affair, and now wishes to return?" },
  { zh: "」洋偽使於東門殺之，而別令賜絹十匹，遂還晉陽，自是居常不悅。", literal: "\" Yang falsely had him killed at the east gate, then separately ordered ten bolts of silk given; he then returned to Jinyang and from this was usually unhappy.", idiomatic: "\" Yang had him killed at the east gate on a pretext, then separately ordered ten bolts of silk given as gift. He returned to Jinyang and from then on was usually unhappy." },
  { zh: "徐之才、宋景業等日陳陰陽雜占，雲宜早受命。", literal: "Xu Zhicai, Song Jingye, and others daily set forth yin-yang and miscellaneous divinations, saying he should early receive the mandate.", idiomatic: "Xu Zhicai, Song Jingye, and others daily urged yin-yang divinations, saying he should receive the mandate early." },
  { zh: "高德政亦敦勸不已。", literal: "Gao Dezheng also pressed him without cease.", idiomatic: "Gao Dezheng also pressed him without cease." },
  { zh: "洋使術士李密卜之，遇《大橫》，曰：「漢文之卦也。", literal: "Yang had diviner Li Mi divine for him; he met Great Horizontal and said: \"It is Emperor Wen of Han's hexagram.", idiomatic: "Yang had diviner Li Mi cast the hexagrams. He met Great Horizontal and said: \"It is Emperor Wen of Han's hexagram." },
  { zh: "」又使宋景業筮之，遇《乾》之《鼎》，曰：「《乾》，君也。", literal: "\" He again had Song Jingye perform milfoil divination; he met Qian changing to Ding and said: \"Qian is the ruler.", idiomatic: "\" He again had Song Jingye perform milfoil divination. He met Qian changing to Ding and said: \"Qian is the ruler." },
  { zh: "《鼎》，五月卦也。", literal: "Ding is the fifth-month hexagram.", idiomatic: "Ding is the fifth-month hexagram." },
  { zh: "宜以仲夏受禪。", literal: "You should receive the abdication in midsummer.", idiomatic: "You should receive the abdication in midsummer." },
  { zh: "」或曰：「五月不可入官，犯之，終於其位。", literal: "\" Someone said: \"The fifth month is not fit to enter office; if you violate this, you will end in your post.", idiomatic: "\" Someone said: \"The fifth month is not fit to enter office; violate that taboo and you will end in your post." },
  { zh: "」景業曰：「王為天子，無復下期，豈得不終於其位乎！", literal: "\" Jingye said: \"When my lord is Son of Heaven there is no next term—how can you not end in your post!", idiomatic: "\" Jingye said: \"When you are Son of Heaven there is no next term—how can you not end in your post!" },
  { zh: "」洋大悅，乃發晉陽。", literal: "\" Yang was greatly pleased and then set out from Jinyang.", idiomatic: "\" Yang was greatly pleased and set out from Jinyang." },
  { zh: "高德政錄在鄴諸事，條進於洋，洋令左右陳山提馳驛繼事條並密書與楊愔。", literal: "Gao Dezheng recorded all affairs at Ye and submitted them item by item to Yang; Yang ordered his attendant Chen Shanti to gallop post-horses with the continued item lists and a secret letter to Yang Yin.", idiomatic: "Gao Dezheng recorded all affairs at Ye and submitted them item by item to Yang. Yang ordered his attendant Chen Shanti to gallop post-horses with the continued lists and a secret letter to Yang Yin." },
  { zh: "是月，山提至鄴，楊愔即召太常卿邢劭等議撰儀注，秘書監魏收草九錫、禪讓、勸進諸文；", literal: "That month Shanti reached Ye; Yang Yin at once summoned Minister of Ceremonies Xing Shao and others to discuss drafting ritual protocols; Secretariat Director Wei Shou drafted the texts for the Nine Bestowals, abdication, and urging to advance;", idiomatic: "That month Shanti reached Ye. Yang Yin at once summoned minister of ceremonies Xing Shao and others to draft ritual protocols; secretariat director Wei Shou drafted the texts for the nine bestowals, abdication, and urging to advance;" },
  { zh: "引魏宗室諸王入北宮，留於東齋。", literal: "he brought in the various princes of the Wei imperial house to the Northern Palace and detained them in the Eastern Study.", idiomatic: "he brought the Wei imperial princes into the Northern Palace and detained them in the Eastern Study." },
  { zh: "甲寅，東魏進洋位相國，總百揆，備九錫。", literal: "On jiayin, Eastern Wei advanced Yang to Chancellor, overall director of the hundred affairs, with the full Nine Bestowals.", idiomatic: "On jiayin, Eastern Wei advanced Yang to chancellor, overall director of the hundred affairs, with the full nine bestowals." },
  { zh: "洋行至前亭，所乘馬忽倒，意甚惡之。", literal: "As Yang traveled he reached Front Pavilion; the horse he rode suddenly fell and he took it as a very ill omen.", idiomatic: "As Yang traveled he reached Front Pavilion. His horse suddenly fell and he took it as a very ill omen." },
  { zh: "至平都城，不復肯進。", literal: "Reaching Pingdu city, he would advance no farther.", idiomatic: "Reaching Pingdu city, he would advance no farther." },
  { zh: "高德政、徐之才苦請曰：「山提先去，恐其漏洩。", literal: "Gao Dezheng and Xu Zhicai urgently pleaded: \"Shanti went ahead first—we fear he will leak the secret.", idiomatic: "Gao Dezheng and Xu Zhicai urgently pleaded: \"Shanti went ahead first—we fear he will leak the secret." },
  { zh: "」即命司馬子如、杜弼馳驛續入，觀察物情。", literal: "\" He at once ordered Sima Ziru and Du Bi to gallop post-horses in continued entry to observe how affairs stood.", idiomatic: "\" He at once ordered Sima Ziru and Du Bi to gallop post-horses after them to observe how affairs stood." },
  { zh: "子如等至鄴，眾人以事勢已決，無敢異言。", literal: "When Ziru and the rest reached Ye, the crowd, seeing the matter already decided, dared no dissenting word.", idiomatic: "When Ziru and the rest reached Ye, seeing the matter already decided, the crowd dared no dissenting word." },
  { zh: "洋至鄴，召夫繼築具集城南。", literal: "When Yang reached Ye, he summoned laborers to continue building implements gathered south of the city.", idiomatic: "When Yang reached Ye, he summoned laborers to continue building the ritual implements gathered south of the city." },
  { zh: "高隆之請曰：「用此何為？", literal: "Gao Longzhi asked: \"What is this for?", idiomatic: "Gao Longzhi asked: \"What is this for?" },
  { zh: "」洋作色曰：「我自有事，君何問為！", literal: "\" Yang changed color and said: \"I have my own affair—why do you ask!", idiomatic: "\" Yang changed color and said: \"I have my own affair—why do you ask!" },
  { zh: "欲族滅邪！", literal: "Do you wish your clan destroyed!", idiomatic: "Do you wish your clan destroyed!" },
  { zh: "」隆之謝而退。", literal: "\" Longzhi apologized and withdrew.", idiomatic: "\" Longzhi apologized and withdrew." },
  { zh: "於是作圜丘，備法物。", literal: "Thereupon they made the Round Mound Altar and prepared ritual implements.", idiomatic: "Thereupon they made the Round Mound Altar and prepared ritual implements." },
  { zh: "丙辰，司空潘樂、侍中張亮、黃門郎趙彥深等求入啟事，東魏孝靜帝在昭陽殿見之。", literal: "On bingchen, Minister of Works Pan Yue, Attendant-in-Ordinary Zhang Liang, Yellow Gate Gentleman Zhao Yanshen, and others asked to enter with reports; Eastern Wei's Emperor Xiaojing received them in Zhaoyang Hall.", idiomatic: "On bingchen, minister of works Pan Yue, attendant-in-ordinary Zhang Liang, yellow gate gentleman Zhao Yanshen, and others asked to enter with reports. Eastern Wei's Emperor Xiaojing received them in Zhaoyang Hall." },
  { zh: "亮曰：「五行遞運，有始有終。", literal: "Liang said: \"The Five Phases pass in turn; there is beginning and there is end.", idiomatic: "Liang said: \"The Five Phases pass in turn; there is beginning and there is end." },
  { zh: "齊王聖德欽明，萬方歸仰，願陛下遠法堯、舜。", literal: "The Prince of Qi's sacred virtue is revered and bright; the ten thousand regions turn to him—may Your Majesty follow Yao and Shun from afar.", idiomatic: "The prince of Qi's sacred virtue is revered and bright; the ten thousand regions turn to him—may Your Majesty follow Yao and Shun from afar." },
  { zh: "」帝斂容曰：「此事推挹已久，謹當遜避。", literal: "\" The emperor composed his face and said: \"This matter has been deferred long; I shall respectfully yield and withdraw.", idiomatic: "\" The emperor composed his face and said: \"This matter has been deferred long; I shall respectfully yield and withdraw." },
  { zh: "」又曰：「若爾，須作制書。", literal: "\" He also said: \"If so, an imperial order must be drafted.", idiomatic: "\" He also said: \"If so, an imperial order must be drafted." },
  { zh: "」中書郎崔劼、裴讓之曰：「制已作訖。", literal: "\" Secretariat Gentlemen Cui Jie and Pei Rangzhi said: \"The order is already drafted.", idiomatic: "\" Secretariat gentlemen Cui Jie and Pei Rangzhi said: \"The order is already drafted." },
  { zh: "」使侍中楊愔進之。", literal: "\" He had Attendant-in-Ordinary Yang Yin present it.", idiomatic: "\" He had attendant-in-ordinary Yang Yin present it." },
  { zh: "東魏主既署，曰：「居朕何所？", literal: "After the Eastern Wei ruler had signed, he said: \"Where shall I dwell?", idiomatic: "After the Eastern Wei ruler had signed, he said: \"Where shall I dwell?" },
  { zh: "」愔對曰：「北城別有館宇。", literal: "\" Yin answered: \"The northern city has separate lodgings.", idiomatic: "\" Yin answered: \"The northern city has separate lodgings." },
  { zh: "」乃下御坐，步就東廊，詠范蔚宗《後漢書‧贊》曰：「獻坐不辰，身播國屯，終我四百，永作虞賓。", literal: "\" He then descended the imperial seat, walked to the eastern corridor, and recited Fan Ye's \"Praise\" in the Book of Later Han: \"The Offered Emperor sat out of season, his person cast about in the state's hardship; he ended our four hundred years, forever to be the guest of Yu.", idiomatic: "\" He descended the imperial seat, walked to the eastern corridor, and recited Fan Ye's praise in the Book of Later Han: \"The offered emperor sat out of season, his person cast about in the state's hardship; he ended our four hundred years, forever to be the guest of Yu." },
  { zh: "」所司請發，帝曰：「古人念遺簪弊履，朕欲與六宮別，可乎？", literal: "\" The responsible office asked to depart; the emperor said: \"The ancients treasured even lost hairpins and worn shoes—may I take leave of the six palaces?", idiomatic: "\" The responsible office asked to depart. The emperor said: \"The ancients treasured even lost hairpins and worn shoes—may I take leave of the six palaces?" },
  { zh: "」高隆之曰：「今日天下猶陛下之天下，況在六宮！", literal: "\" Gao Longzhi said: \"Today the realm is still Your Majesty's realm—how much more the six palaces!", idiomatic: "\" Gao Longzhi said: \"Today the realm is still Your Majesty's realm—how much more the six palaces!" },
  { zh: "」帝步入，與妃嬪已下別，舉宮皆哭。", literal: "\" The emperor walked in and took leave of consorts and below; the whole palace wept.", idiomatic: "\" The emperor walked in and took leave of consorts and attendants; the whole palace wept." },
  { zh: "趙國李嬪誦陳思王詩云：「王其愛玉體，俱享黃發期。", literal: "Lady Li of Zhao recited Prince Si of Chen's poem: \"My lord, cherish your jade body and together enjoy the yellow-hair years.", idiomatic: "Lady Li of Zhao recited Prince Si of Chen's poem: \"My lord, cherish your jade body and together enjoy the years of gray hair." },
  { zh: "」直長趙道德以故犢車一乘候於東閣，帝登車，道德超上抱之，帝叱之曰：「朕自畏天順人，何物奴敢逼人如此！", literal: "\" Direct Attendant Zhao Daode waited at the eastern gate with one old ox-cart; the emperor mounted the cart; Daode sprang up and embraced him; the emperor shouted: \"I myself fear Heaven and follow the people—what low slave dares press a man like this!", idiomatic: "\" Direct attendant Zhao Daode waited at the eastern gate with one old ox-cart. The emperor mounted; Daode sprang up and embraced him. The emperor shouted: \"I myself fear Heaven and follow the people—what low slave dares press a man like this!" },
  { zh: "」道德猶不下。", literal: "\" Daode still would not descend.", idiomatic: "\" Daode still would not descend." },
  { zh: "出雲龍門，王公百僚拜辭，高隆之灑泣。", literal: "He went out through Cloud Dragon Gate; princes, dukes, and the hundred officials bowed in farewell; Gao Longzhi wept freely.", idiomatic: "He went out through Cloud Dragon Gate. Princes, dukes, and the hundred officials bowed in farewell. Gao Longzhi wept freely." },
  { zh: "遂入北城，居司馬子如南宅，遣太尉彭城王韶等奉璽綬，禪位於齊。", literal: "He then entered the northern city, dwelt in Sima Ziru's southern residence, and sent Grand Commandant Prince Shao of Pengcheng and others to present seal and sash and abdicate the throne to Qi.", idiomatic: "He entered the northern city, dwelt in Sima Ziru's southern residence, and sent grand commandant Prince Shao of Pengcheng and others to present seal and sash and abdicate the throne to Qi." },
  { zh: "戊午，齊王即皇帝位於南郊，大赦，改元天保。", literal: "On wuwu, the Prince of Qi took the imperial throne at the southern suburb, proclaimed a general amnesty, and changed the era name to Tianbao.", idiomatic: "On wuwu, the prince of Qi took the imperial throne at the southern suburb, proclaimed a general amnesty, and changed the era name to Tianbao." },
  { zh: "自魏敬宗以來，百官絕祿，至是始復給之。", literal: "Since Emperor Jingzong of Wei, the hundred offices had had no salaries; only now were they restored.", idiomatic: "Since Emperor Jingzong of Wei, officials had received no salaries; only now were they restored." },
  { zh: "己未，封東魏主為中山王，待以不臣之禮。", literal: "On jiwei, he enfeoffed the Eastern Wei ruler as Prince of Zhongshan and treated him with the ceremony due one who is not a subject.", idiomatic: "On jiwei, he enfeoffed the Eastern Wei ruler as prince of Zhongshan and treated him with the ceremony due one who is not a subject." },
  { zh: "追尊齊獻武王為獻武皇帝，廟號太祖，後改為高祖；", literal: "He posthumously honored Prince of Qi Xianwu as Emperor Xianwu, temple name Taizu, later changed to Gaozu;", idiomatic: "He posthumously honored Prince Xianwu of Qi as Emperor Xianwu, temple name Taizu, later changed to Gaozu;" },
  { zh: "文襄王為文襄皇帝，廟號世宗。", literal: "Prince Wenxiang as Emperor Wenxiang, temple name Shizong.", idiomatic: "Prince Wenxiang as Emperor Wenxiang, temple name Shizong." },
  { zh: "辛酉，尊王太后婁氏為皇太后。", literal: "On xinyou, he honored Grand Consort Lou as Empress Dowager.", idiomatic: "On xinyou, he honored Grand Consort Lou as empress dowager." },
  { zh: "乙丑，降魏朝封爵有差，其宣力霸朝及西、南投化者，不在降限。", literal: "On yichou, he reduced Wei-dynasty enfeoffments and ranks by degrees; those who had proclaimed strength for the hegemon court and those who had submitted from west and south were not within the reduction limit.", idiomatic: "On yichou, he reduced Wei-dynasty enfeoffments and ranks by degrees; those who had served the hegemon court and those who had submitted from west and south were exempt." },
  { zh: "文成侯寧起兵於吳，有眾萬人，己巳，進攻吳郡；", literal: "Marquis Ning of Wencheng raised troops in Wu with ten thousand men; on jisi, he advanced to attack Wu commandery;", idiomatic: "Marquis Ning of Wencheng raised troops in Wu with ten thousand men. On jisi he advanced to attack Wu commandery;" },
  { zh: "行吳郡事侯子榮逆擊，殺之。", literal: "Acting Wu Administrator Hou Zirong struck back and killed him.", idiomatic: "Acting Wu administrator Hou Zirong struck back and killed him." },
  { zh: "寧，范之弟也。", literal: "Ning was Fan's younger brother.", idiomatic: "Ning was Fan's younger brother." },
  { zh: "子榮因縱兵大掠郡境。", literal: "Zirong then let his troops plunder the commandery borders greatly.", idiomatic: "Zirong then let his troops plunder the whole commandery." },
  { zh: "自晉氏度江，三吳最為富庶，貢賦商旅，皆出其地。", literal: "Since the Jin house crossed the river, the Three Wu had been richest; tribute, taxes, merchants and travelers all came from that land.", idiomatic: "Since the Jin house crossed the river, the Three Wu had been richest; tribute, taxes, and merchants all flowed from that land." },
  { zh: "及侯景之亂，掠金帛既盡，乃掠人而食之，或賣於北境，遺民殆盡矣。", literal: "When Hou Jing's rebellion came, after gold and silk were plundered clean they plundered men to eat them, or sold them to the northern borders; survivors were nearly all gone.", idiomatic: "When Hou Jing's rebellion came, after gold and silk were stripped bare they plundered men for food, or sold them to the northern borders; survivors were nearly gone." },
  { zh: "是時，唯荊、益所部尚完實，太尉、益州刺史武陵王紀移告征、鎮，使世子圓照帥兵三萬受湘東王節度。", literal: "At this time only the parts held by Jing and Yi remained intact; Grand Commandant and Yizhou Inspector Prince Ji of Wuling sent notice to the campaign armies and garrisons, making his heir Yuanzhao lead thirty thousand men to accept Prince of Xiangdong Yi's command.", idiomatic: "At this time only the domains of Jing and Yi remained intact. Grand commandant and Yizhou inspector Prince Ji of Wuling sent notice to the campaign armies and garrisons, ordering his heir Yuanzhao to lead thirty thousand men under Prince Xiao Yi of Xiangdong." },
  { zh: "圓照軍至巴水，繹授以信州刺史，令屯白帝，未許東下。", literal: "Yuanzhao's army reached Bashui; Yi made him Xinzhou Inspector and ordered him to camp at Baidi, not permitting him to go east.", idiomatic: "Yuanzhao's army reached the Bashui. Yi made him Xinzhou inspector, ordered him to camp at Baidi, and would not let him march east." },
  { zh: "六月，辛巳，以南郡王大連行揚州事。", literal: "In the sixth month, on xinsi, Prince Dalian of Nan commandery was made acting Yangzhou affairs.", idiomatic: "In the sixth month, on xinsi, Prince Dalian of Nan commandery was made acting Yangzhou affairs." },
  { zh: "江夏王大款、山陽王大成、宜都王大封自信安間道奔江陵。", literal: "Prince Dakuan of Jiangxia, Prince Dacheng of Shanyang, and Prince Dafeng of Yidu from Xin'an by hidden paths fled to Jiangling.", idiomatic: "Prince Dakuan of Jiangxia, Prince Dacheng of Shanyang, and Prince Dafeng of Yidu fled from Xin'an by hidden paths to Jiangling." },
  { zh: "齊主封宗室高岳等十人、功臣庫狄乾等七人皆為王。", literal: "The Qi ruler enfeoffed ten clansmen including Gao Yue and seven meritorious ministers including Kudi Gan all as kings.", idiomatic: "The Qi ruler enfeoffed ten clansmen including Gao Yue and seven meritorious ministers including Kudi Gan as kings." },
  { zh: "癸未，封弟浚為永安王，淹為平陽王，浟為彭城王，演為常山王，渙為上黨王，淯為襄城王，湛為長廣王，湝為任城王，湜為高陽王，濟為博陵王，凝為新平王，潤為馮翊王，洽為漢陽王。", literal: "On guiwei, he enfeoffed his younger brothers Jun as Prince of Yong'an, Yan as Prince of Pingyang, You as Prince of Pengcheng, Yan as Prince of Changshan, Huan as Prince of Shangdang, Yu as Prince of Xiangcheng, Zhan as Prince of Changgang, Jie as Prince of Rencheng, Shi as Prince of Gaoyang, Ji as Prince of Boling, Ning as Prince of Xinping, Run as Prince of Fengyi, and Qia as Prince of Hanyang.", idiomatic: "On guiwei, he enfeoffed his younger brothers: Jun as prince of Yong'an, Yan as prince of Pingyang, You as prince of Pengcheng, Yan as prince of Changshan, Huan as prince of Shangdang, Yu as prince of Xiangcheng, Zhan as prince of Changgang, Jie as prince of Rencheng, Shi as prince of Gaoyang, Ji as prince of Boling, Ning as prince of Xinping, Run as prince of Fengyi, and Qia as prince of Hanyang." },
  { zh: "鄱陽王范既卒，侯瑱依莊鐵，鐵忌之；", literal: "After Prince of Poyang Fan had died, Hou Zhen relied on Zhuang Tie; Tie resented him;", idiomatic: "After Prince Fan of Poyang died, Hou Zhen relied on Zhuang Tie; Tie resented him;" },
  { zh: "瑱自安，丙戌，詐引鐵謀事，因殺之，自據豫章。", literal: "Zhen felt secure; on bingxu, he falsely summoned Tie to discuss plans and killed him, then seized Yuzhang for himself.", idiomatic: "Zhen felt secure; on bingxu, he lured Zhuang Tie under pretense of counsel and killed him, then seized Yuzhang for himself." },
  { zh: "尋陽王大心遣徐嗣徽夜襲湓城，安南侯恬、裴之橫等擊走之。", literal: "Prince Daxin of Xunyang sent Xu Sihui in a night raid on Pencheng; Marquis Tian of Annan, Pei Zhiheng, and others struck and drove him off.", idiomatic: "Prince Daxin of Xunyang sent Xu Sihui in a night raid on Pencheng; Marquis Tian of Annan, Pei Zhiheng, and others struck and drove him off." },
  { zh: "齊主娶趙郡李希宗之女，生子殷及紹德；", literal: "The Qi emperor married the daughter of Li Xizong of Zhao commandery and had sons Yin and Shaode.", idiomatic: "The Qi emperor married the daughter of Li Xizong of Zhao commandery and had sons Yin and Shaode." },
  { zh: "又納段韶之妹。", literal: "He also took Duan Shao's younger sister.", idiomatic: "He also took Duan Shao's younger sister as consort." },
  { zh: "及將建中宮，高隆之、高德政欲結勳貴之援，乃言：「漢婦人不可為天下母，宜更擇美配。", literal: "When he was about to establish the empress, Gao Longzhi and Gao Dezheng wished to win support from meritorious nobles and said, \"A Han woman cannot be mother to the realm; a finer match should be chosen.", idiomatic: "When he was about to name an empress, Gao Longzhi and Gao Dezheng, seeking allies among the meritorious nobility, said, \"A Han woman cannot be mother to the realm—a finer match should be chosen." },
  { zh: "」帝不從。", literal: "\" The emperor would not heed them.", idiomatic: "\" The emperor would not heed them." },
  { zh: "丁亥，立李氏為皇后，以段氏為昭儀，子殷為皇太子。", literal: "On dinghai, he made Lady Li empress, Lady Duan a Lady of Bright Deportment, and son Yin crown prince.", idiomatic: "On dinghai, he made Lady Li empress, Lady Duan a Lady of Bright Deportment, and son Yin crown prince." },
  { zh: "庚寅，以庫狄干為太宰，彭樂為太尉，潘相樂為司徒，司馬子如為司空。", literal: "On gengyin, he made Kudi Gan Grand Preceptor, Peng Yue Grand Commandant, Pan Xiangle Minister of Works, and Sima Ziru Minister of the Masses.", idiomatic: "On gengyin, he made Kudi Gan Grand Preceptor, Peng Yue Grand Commandant, Pan Xiangle Minister of Works, and Sima Ziru Minister of the Masses." },
  { zh: "辛卯，以清河王岳為司州牧。", literal: "On xinmao, he made Prince Yue of Qinghe Governor of Sizhou.", idiomatic: "On xinmao, he made Prince Yue of Qinghe Governor of Sizhou." },
  { zh: "侯景以羊鴉仁為五兵尚書。", literal: "Hou Jing made Yang Yaren Minister of the Five Arms.", idiomatic: "Hou Jing made Yang Yaren Minister of the Five Arms." },
  { zh: "庚子，鴉仁出奔江西，將赴江陵，至東莞，盜疑其懷金，邀殺之。", literal: "On gengzi, Yaren fled west of the river, intending to go to Jiangling; reaching Dongguan, bandits suspected he carried gold and waylaid and killed him.", idiomatic: "On gengzi, Yaren fled west of the river toward Jiangling; at Dongguan, bandits suspected he carried gold and waylaid and killed him." },
  { zh: "魏人欲令岳陽王察發哀嗣位，察辭，不受。", literal: "The Wei men wished Prince Cha of Yueyang to proclaim mourning and succeed to the throne; Cha declined and would not accept.", idiomatic: "The Western Wei court wished Prince Cha of Yueyang to proclaim mourning and succeed to the throne; Cha declined." },
  { zh: "丞相泰使榮權冊命察為梁王，始建台，置百官。", literal: "Chancellor Tai sent Rong Quan with patent and mandate to enfeoff Cha as Prince of Liang; he first raised a headquarters and established the hundred offices.", idiomatic: "Chancellor Yuwen Tai sent Rong Quan with patent and mandate to enfeoff Cha as Prince of Liang; Cha first raised a headquarters and established the hundred offices." },
  { zh: "陳霸先修崎頭古城，徙居之。", literal: "Chen Baxian repaired the old city at Qitou and moved his seat there.", idiomatic: "Chen Baxian repaired the old city at Qitou and moved his seat there." },
  { zh: "初，燕昭成帝奔高麗，使其族人馮業以三百人浮海奔宋，因留新會。", literal: "Earlier, Emperor Zhaocheng of Yan fled to Goguryeo and had his clansman Feng Ye take three hundred men across the sea to flee to Song, and they remained at Xinhui.", idiomatic: "Earlier, Emperor Zhaocheng of Yan fled to Goguryeo and sent his clansman Feng Ye with three hundred men across the sea to Song territory; they settled at Xinhui." },
  { zh: "自業至孫融，世為羅州刺史，融子寶為高涼太守。", literal: "From Ye down to grandson Rong, the line served as Inspectors of Luozhou generation after generation; Rong's son Bao was Administrator of Gaoliang.", idiomatic: "From Ye down to grandson Rong, the line held Luozhou generation after generation; Rong's son Bao was administrator of Gaoliang." },
  { zh: "高涼洗氏，世為蠻酋，部落十餘萬家，有女，多籌略，善用兵，諸洞皆服其信義；", literal: "The Xi clan of Gaoliang had for generations been chieftains among the barbarians, with more than a hundred thousand households in their tribes; they had a daughter of great stratagem who excelled at arms, and all the cave settlements trusted her integrity.", idiomatic: "The Xi of Gaoliang had for generations been chieftains among the hill peoples, with more than a hundred thousand households in their tribes; they had a daughter of keen stratagem who excelled at arms, and every cave settlement trusted her word." },
  { zh: "融聘以為寶婦。", literal: "Rong betrothed her to Bao as wife.", idiomatic: "Rong betrothed her to Bao as his wife." },
  { zh: "融雖累世為方伯，非其土人，號令不行；", literal: "Though Rong had for generations been a frontier lord, he was not native to the soil and his orders did not take effect.", idiomatic: "Though Rong had for generations been a frontier lord, he was not native to the land and his orders did not take effect." },
  { zh: "洗氏約束本宗，使從民禮，每與寶參決辭訟，首領有犯，雖親戚無所縱捨，由是馮氏始得行其政。", literal: "Lady Xi restrained her own clan, made them follow civil rites, joined Bao in judging lawsuits, and when chieftains offended showed no lenience even to kin; thereby the Feng line at last could enforce its rule.", idiomatic: "Lady Xi restrained her own clan, made them follow civil law, joined Bao in judging lawsuits, and when chieftains offended showed no lenience even to kin—only then could the Feng line enforce its rule." },
  { zh: "高州刺史李遷仕據大皋口，遣使召寶，寶欲往，洗氏止之曰：「刺史無故不應召太守，必欲詐君共反耳。", literal: "Gaozhou Inspector Li Qianshi held Dagao Pass and sent envoys summoning Bao; Bao wished to go; Lady Xi stopped him, saying, \"An inspector should not summon an administrator without cause—he surely means to trick you into rebellion with him.", idiomatic: "Gaozhou inspector Li Qianshi held Dagao Pass and summoned Bao; Bao wished to go; Lady Xi stopped him: \"An inspector should not summon an administrator without cause—he surely means to trick you into rebellion with him." },
  { zh: "」寶曰：「何以知之？", literal: "\" Bao said, \"How do you know?", idiomatic: "\" Bao said, \"How do you know?" },
  { zh: "」洗氏曰：「刺史被召援台，乃稱有疾，鑄兵聚眾而後召君；", literal: "\" Lady Xi said, \"The inspector was summoned to aid the capital yet claims illness, casts weapons and gathers troops, and only then summons you.", idiomatic: "\" Lady Xi said, \"The inspector was summoned to aid the capital yet claims illness, casts weapons and gathers troops, and only then summons you." },
  { zh: "此必欲質君以發君之兵也，願且無往以觀其變。", literal: "He surely means to hold you hostage to raise your troops; I beg you not go yet and watch how matters turn.", idiomatic: "He surely means to hold you hostage to raise your troops; do not go yet—watch how matters turn." },
  { zh: "」數日，遷仕果反，遣主帥杜平虜將兵入灨石，城魚梁以逼南康，陳霸先使周文育擊之。", literal: "\" Within days Qianshi indeed rebelled, sent commander Du Pinglu with troops into Ganshi, walled Yuliang to press Nankang; Chen Baxian sent Zhou Wenyu to strike him.", idiomatic: "\" Within days Qianshi rebelled, sent commander Du Pinglu into Ganshi, walled Yuliang to press Nankang; Chen Baxian sent Zhou Wenyu against him." },
  { zh: "洗氏謂寶曰：「平虜，驍將也，今入贛石與官軍相拒，勢未得還，遷仕在州，無能為也。", literal: "Lady Xi told Bao, \"Pinglu is a fierce general; now he has entered Ganshi to contend with the government army and cannot soon return; Qianshi in the province can do nothing.", idiomatic: "Lady Xi told Bao, \"Pinglu is a fierce general; now he is locked in Ganshi against the government army and cannot soon return—Qianshi in the province is helpless." },
  { zh: "君若自往，必有戰鬥，宜遣使卑辭厚禮告之曰：『身未敢出，欲遣婦參。", literal: "If you go yourself there will surely be battle; better send envoys with humble words and rich gifts, saying, 'I dare not come myself and wish to send my wife to attend.", idiomatic: "If you go yourself there will surely be battle; better send envoys with humble words and rich gifts, saying, 'I dare not come myself and wish to send my wife to attend." },
  { zh: "』彼聞之，必喜而無備。", literal: "' When he hears this he will be pleased and unguarded.", idiomatic: "' When he hears that he will be pleased and drop his guard." },
  { zh: "我將千餘人，步擔雜物，唱言輸賧，得至柵下，破之必矣。", literal: "I shall take more than a thousand men, carrying goods on foot, proclaiming tribute delivery; once we reach the palisade we shall surely break them.", idiomatic: "I shall take more than a thousand men on foot with bundled goods, proclaiming tribute delivery; once we reach the palisade we shall break them." },
  { zh: "」寶從之。", literal: "\" Bao followed her plan.", idiomatic: "\" Bao followed her plan." },
  { zh: "遷仕果不設備，洗氏襲擊，大破之，遷仕走保寧都。", literal: "Qianshi indeed made no preparations; Lady Xi struck by surprise and routed him; Qianshi fled to hold Ningdu.", idiomatic: "Qianshi left himself unguarded; Lady Xi struck by surprise and routed him; Qianshi fled to hold Ningdu." },
  { zh: "文育亦擊走平虜，據其城。", literal: "Wenyu also struck and drove off Pinglu and seized his city.", idiomatic: "Wenyu also drove off Pinglu and seized his city." },
  { zh: "洗氏與霸先會於灨石，還，謂寶曰：「陳都督非常人也，甚得眾心，必能平賊，君宜厚資之。", literal: "Lady Xi met Baxian at Ganshi; returning, she told Bao, \"Commander Chen is no ordinary man; he wins men's hearts and will surely quell the rebels—you should support him generously.", idiomatic: "Lady Xi met Baxian at Ganshi; returning, she told Bao, \"Commander Chen is no ordinary man; he wins men's hearts and will quell the rebels—you should support him generously." },
  { zh: "湘東王繹以霸先為豫州刺史，領豫章內史。", literal: "Prince Yi of Xiangdong made Baxian Inspector of Yuzhou and concurrent Administrator of Yuzhang.", idiomatic: "Prince Xiao Yi of Xiangdong made Baxian Inspector of Yuzhou and concurrent Administrator of Yuzhang." },
  { zh: "辛丑，裴之橫攻稽亭，徐嗣徽擊走之。", literal: "On xinchou, Pei Zhiheng attacked Jiting; Xu Sihui struck and drove him off.", idiomatic: "On xinchou, Pei Zhiheng attacked Jiting; Xu Sihui struck and drove him off." },
  { zh: "秋，七月，辛亥，齊立世宗妃元氏為文襄皇后，宮曰靜德。", literal: "In autumn, the seventh month, on xinhai, Qi established the Shizong consort of the Yuan clan as Empress Wenxiang, with palace name Jingde.", idiomatic: "In autumn, the seventh month, on xinhai, Qi established Shizong's consort of the Yuan clan as Empress Wenxiang, with palace name Jingde." },
  { zh: "又封世宗子孝琬為河間王，孝瑜為河南王。", literal: "He also enfeoffed Shizong's sons Xiaowan as Prince of Hejian and Xiaoyu as Prince of Henan.", idiomatic: "He also enfeoffed Shizong's sons Xiaowan as Prince of Hejian and Xiaoyu as Prince of Henan." },
  { zh: "乙卯，以尚書令封隆之錄尚書事，尚書左僕射平陽王淹為尚書令。", literal: "On yimao, he made Minister of Works Feng Longzhi Recorder of the Affairs of the Masters of Writing and Left Vice Minister of Works Prince Yan of Pingyang Minister of Works.", idiomatic: "On yimao, he made Minister of Works Feng Longzhi Recorder of the Affairs of the Masters of Writing and Left Vice Minister Prince Yan of Pingyang Minister of Works." },
  { zh: "辛酉，梁王察入朝於魏。", literal: "On xinyou, Prince of Liang Cha entered court in Wei.", idiomatic: "On xinyou, Prince of Liang Cha entered court at the Wei capital." },
  { zh: "初，東魏遣儀同武威牒雲洛等迎鄱陽世子嗣，使鎮皖城。", literal: "Earlier, Eastern Wei sent Equal in Honor to the Three Dukes Wuwei Dieyun Luo and others to welcome Poyang Heir Si and station him at Wancheng.", idiomatic: "Earlier, Eastern Wei sent Dieyun Luo of Wuwei, Equal in Honor to the Three Dukes, and others to welcome Poyang heir Si and station him at Wancheng." },
  { zh: "嗣未及行，任約軍至，洛等引去；", literal: "Si had not yet set out when Ren Yue's army arrived; Luo and the others withdrew.", idiomatic: "Si had not yet set out when Ren Yue's army arrived; Luo and the others withdrew." },
  { zh: "嗣遂失援，出戰，敗死。", literal: "Si thus lost support, went out to battle, was defeated, and died.", idiomatic: "Si thus lost support, went out to battle, was defeated, and died." },
  { zh: "約遂略地至湓城，尋陽王大心遣司馬韋質出戰而敗，帳下猶有戰士千餘人，鹹勸大心走保建州；", literal: "Yue then raided as far as Pencheng; Prince Daxin of Xunyang sent Chief Administrator Wei Zhi out to fight and was defeated; under his tent there remained more than a thousand fighting men, and all urged Daxin to flee and hold Jianzhou.", idiomatic: "Yue then raided as far as Pencheng; Prince Daxin of Xunyang sent chief administrator Wei Zhi out to fight and was defeated; more than a thousand warriors still stood under his tent, and all urged Daxin to flee and hold Jianzhou." },
  { zh: "大心不能用，戊辰，以江州降約。", literal: "Daxin would not follow them; on wuchen he surrendered Jiangzhou to Yue.", idiomatic: "Daxin would not listen; on wuchen he surrendered Jiangzhou to Yue." },
  { zh: "先是，大心使前太子洗馬韋臧鎮建昌，有甲士五千，聞尋陽不守，欲帥眾奔江陵，未發，為麾下所殺。", literal: "Earlier, Daxin had sent former Crown Prince Attendant Wei Zang to garrison Jianchang with five thousand armored men; hearing Xunyang had not held, he wished to lead his force to Jiangling; before he set out, his subordinates killed him.", idiomatic: "Earlier, Daxin had sent former crown prince attendant Wei Zang to garrison Jianchang with five thousand armored men; hearing Xunyang had fallen, he wished to lead his force to Jiangling; before he could march, his own men killed him." },
  { zh: "臧，粲之子也。", literal: "Zang was Can's son.", idiomatic: "Zang was Can's son." },
  { zh: "於慶略地至豫章，侯瑱屈，降之，慶送瑱建康。", literal: "Yu Qing raided as far as Yuzhang; Hou Zhen submitted and surrendered; Qing sent Zhen to Jiankang.", idiomatic: "Yu Qing raided as far as Yuzhang; Hou Zhen submitted; Qing sent Zhen to Jiankang." },
  { zh: "景以瑱姓，待之甚厚，留其妻子及弟為質，遣瑱慶徇蠡南諸郡，以瑱湘州刺史。", literal: "Jing, because of Zhen's surname, treated him very generously, kept his wife, children, and younger brother as hostages, sent Zhen with Qing to overrun the southern counties of Li, and made Zhen Inspector of Xiangzhou.", idiomatic: "Hou Jing, because of Zhen's surname, treated him generously, kept his wife, children, and younger brother as hostages, sent Zhen with Qing to overrun the southern counties of Li, and made Zhen Inspector of Xiangzhou." },
  { zh: "初，巴山人黃法□，有勇力，侯景之亂，合徒眾保鄉里。", literal: "Earlier, Huang Fa□ of Bashan, brave and strong, during Hou Jing's rebellion gathered followers to protect his home district.", idiomatic: "Earlier, Huang Fa□ of Bashan, brave and strong, during Hou Jing's rebellion gathered followers to protect his home district." },
  { zh: "太守賀詡下江州，命法□監郡事。", literal: "Administrator He Xu went down to Jiangzhou and ordered Fa□ to oversee commandery affairs.", idiomatic: "Administrator He Xu went down to Jiangzhou and ordered Fa□ to oversee commandery affairs." },
  { zh: "法□屯新淦，於慶自豫章分兵襲新水金，法□敗之。", literal: "Fa□ encamped at Xingan; Yu Qing from Yuzhang divided his force to raid Xinshuijin; Fa□ defeated him.", idiomatic: "Fa□ encamped at Xingan; Yu Qing from Yuzhang divided his force to raid Xinshuijin; Fa□ defeated him." },
  { zh: "陳霸先使周文育進軍擊慶，法□引兵會之。", literal: "Chen Baxian sent Zhou Wenyu advancing to strike Qing; Fa□ led troops to join him.", idiomatic: "Chen Baxian sent Zhou Wenyu to strike Qing; Fa□ led troops to join him." },
  { zh: "邵陵王綸聞任約將至，使司馬蔣思安將精兵五千襲之，約眾潰；", literal: "Prince Lun of Shaoling heard Ren Yue was coming, sent Chief Administrator Jiang Si'an with five thousand elite troops to surprise him; Yue's force collapsed.", idiomatic: "Prince Lun of Shaoling heard Ren Yue was coming and sent chief administrator Jiang Si'an with five thousand elite troops to surprise him; Yue's force collapsed." },
  { zh: "思安不設備，約收兵襲之，思安敗走。", literal: "Si'an made no preparations; Yue gathered his troops and struck him; Si'an was defeated and fled.", idiomatic: "Si'an left himself unguarded; Yue rallied his men and struck back; Si'an was defeated and fled." },
  { zh: "湘東王繹改宜都為宜州，以王琳為刺史。", literal: "Prince Yi of Xiangdong changed Yidu to Yizhou and made Wang Lin its inspector.", idiomatic: "Prince Xiao Yi of Xiangdong changed Yidu to Yizhou and made Wang Lin its inspector." },
  { zh: "是月，以南郡王大連為江州刺史。", literal: "That month he made Prince Dalian of Nanjun Inspector of Jiangzhou.", idiomatic: "That month he made Prince Dalian of Nanjun Inspector of Jiangzhou." },
  { zh: "魏丞相泰以齊主稱帝，帥諸軍討之。", literal: "Wei Chancellor Tai, because the Qi emperor had claimed the throne, led the armies to attack him.", idiomatic: "Chancellor Yuwen Tai, because the Qi emperor had claimed the throne, led the armies against him." },
  { zh: "以齊王郭鎮隴右，征秦州刺史宇文導為大將軍、都督二十三州諸軍事，屯咸陽，鎮關中。", literal: "He made Prince Guo of Qi garrison Longyou, summoned Qinzhou Inspector Yuwen Dao as Grand General and Commander of Military Affairs in Twenty-three Provinces, encamped at Xianyang, and garrisoned Guanzhong.", idiomatic: "He made Prince Guo of Qi garrison Longyou, summoned Qinzhou inspector Yuwen Dao as Grand General and Commander of Military Affairs in Twenty-three Provinces, encamped at Xianyang, and held Guanzhong." },
  { zh: "益州沙門孫天英帥徒數千人夜攻州城，武陵王紀與戰，斬之。", literal: "The monk Sun Tianying of Yizhou led several thousand followers in a night attack on the provincial city; Prince Ji of Wuling fought him and beheaded him.", idiomatic: "The monk Sun Tianying of Yizhou led several thousand followers in a night attack on the provincial city; Prince Ji of Wuling fought him and beheaded him." },
  { zh: "邵陵王綸大修鎧仗，將討侯景。", literal: "Prince Lun of Shaoling greatly repaired armor and weapons, intending to attack Hou Jing.", idiomatic: "Prince Lun of Shaoling greatly repaired armor and weapons, intending to attack Hou Jing." },
  { zh: "湘東王繹惡之，八月，甲午，遣左衛將軍王僧辯、信州刺史鮑泉等帥舟師一萬東趣江、郢，聲言拒任約，且雲迎邵陵王還江陵，授以湘州。", literal: "Prince Yi of Xiangdong resented this; in the eighth month, on jiawu, he sent Left Guard General Wang Senbian, Xinzhou Inspector Bao Quan, and others leading ten thousand men in ships east toward Jiang and Ying, proclaiming resistance to Ren Yue while also saying he would welcome Prince Lun back to Jiangling and grant him Xiangzhou.", idiomatic: "Prince Xiao Yi of Xiangdong resented this; in the eighth month, on jiawu, he sent Left Guard General Wang Senbian, Xinzhou inspector Bao Quan, and others with ten thousand men in ships east toward Jiang and Ying, proclaiming resistance to Ren Yue while also saying he would welcome Prince Lun back to Jiangling and grant him Xiangzhou." },
  { zh: "齊主初立，勵精為治。", literal: "When the Qi emperor first took the throne, he strove diligently in government.", idiomatic: "When the Qi emperor first took the throne, he strove diligently in government." },
  { zh: "趙道德以事屬黎陽太守清河房超，超不發書，棓殺其使；", literal: "Zhao Daode entrusted a matter to Liyang Administrator Fang Chao of Qinghe; Chao would not release the document and clubbed his messenger to death.", idiomatic: "Zhao Daode entrusted a matter to Liyang administrator Fang Chao of Qinghe; Chao would not release the document and clubbed his messenger to death." },
  { zh: "齊主善之，命守宰各設棓以誅屬請之使。", literal: "The Qi emperor approved this and ordered every prefect and magistrate to set up clubs to execute messengers making improper requests.", idiomatic: "The Qi emperor approved and ordered every prefect and magistrate to keep clubs at hand to execute messengers making improper requests." },
  { zh: "久之，都官中郎宋軌奏曰：「若受使請賕，猶致大戮，身為枉法，何以加罪！", literal: "After long time, Palace Attendant of the Capital Bureau Song Gui memorialized, saying, \"If accepting bribes through messengers still brings death, how can one add punishment for bending the law oneself!", idiomatic: "After long time, palace attendant Song Gui of the Capital Bureau memorialized: \"If accepting bribes through messengers still brings death, how can one add punishment for bending the law oneself!" },
  { zh: "」乃罷之。", literal: "\" Thereupon the practice was abolished.", idiomatic: "\" Thereupon the practice was abolished." },
  { zh: "司都功曹張老上書請定齊律，詔右僕射薛琡等取魏《麟趾格》，更討論損益之。", literal: "Chief Clerk Zhang Lao of the Capital Bureau submitted a memorial asking to fix Qi law; an edict ordered Right Vice Minister Xue Ju and others to take Wei's Linzhi Code and revise it through discussion of what to add or cut.", idiomatic: "Chief clerk Zhang Lao of the Capital Bureau asked that Qi law be fixed; an edict ordered Right Vice Minister Xue Ju and others to take Wei's Linzhi Code and revise it through discussion of what to add or cut." },
  { zh: "齊主簡練六坊之人，每一人必當百人，任其臨陳必死，然後取之，謂之「百保鮮卑」。", literal: "The Qi emperor selected and trained men of the six wards so that each one must equal a hundred, taking only those who would surely die facing battle, and called them the \"Hundred-Guard Xianbei.\"", idiomatic: "The Qi emperor selected men of the six wards so that each must equal a hundred, taking only those who would die facing battle without flinching, and called them the \"Hundred-Guard Xianbei.\"" },
  { zh: "又簡華人之勇力絕倫者，謂之「勇士」，以備邊要。", literal: "He also selected Chinese of unmatched courage and strength, called them \"Warriors,\" to guard critical frontiers.", idiomatic: "He also selected Chinese of unmatched courage and strength, called them \"Warriors,\" to guard critical frontiers." },
  { zh: "始立九等之戶，富者稅其錢，貧者役其力。", literal: "He first established nine grades of households: the rich were taxed in coin, the poor in labor.", idiomatic: "He first established nine grades of households: the rich were taxed in coin, the poor in labor." },
  { zh: "九月，丁巳，魏軍發長安。", literal: "In the ninth month, on dingsi, the Wei army set out from Chang'an.", idiomatic: "In the ninth month, on dingsi, the Wei army set out from Chang'an." },
  { zh: "王僧辯軍至鸚鵡洲，郢州司馬劉龍虎等潛送質於僧辯，邵陵王綸聞之，遣其子威正侯礩將兵擊之，龍虎敗，奔於僧辯。", literal: "Wang Senbian's army reached Parrot Islet; Yingzhou Chief Administrator Liu Longhu and others secretly sent hostages to Senbian; Prince Lun of Shaoling heard of it and sent his son Marquis Li of Weizheng with troops to strike them; Longhu was defeated and fled to Senbian.", idiomatic: "Wang Senbian's army reached Parrot Islet; Yingzhou chief administrator Liu Longhu and others secretly sent hostages to Senbian; Prince Lun of Shaoling heard and sent his son Marquis Li of Weizheng to strike them; Longhu was defeated and fled to Senbian." },
  { zh: "綸以書責僧辯曰：「將軍前年殺人之侄，今歲伐人之兄，以此求榮，恐天下不許！", literal: "Lun wrote Senbian a letter of reproach, saying, \"General, last year you killed a man's nephew; this year you attack a man's elder brother—with this you seek glory, and I fear the realm will not allow it!", idiomatic: "Lun wrote Senbian a letter of reproach: \"General, last year you killed a man's nephew; this year you attack a man's elder brother—with this you seek glory, and I fear the realm will not allow it!" },
  { zh: "」僧辯送書於湘東王繹，繹命進軍。", literal: "\" Senbian forwarded the letter to Prince Yi of Xiangdong; Yi ordered the advance.", idiomatic: "\" Senbian forwarded the letter to Prince Xiao Yi of Xiangdong; Yi ordered the advance." },
  { zh: "辛酉，綸集其麾下於西園，涕泣言曰：「我本無他，志在滅賊，湘東常謂與之爭帝，遂爾見伐。", literal: "On xinyou, Lun gathered his followers in the Western Garden and said through tears, \"I had no other aim but to destroy the rebels; Xiangdong always believed I contended with him for the throne, and so I am attacked.", idiomatic: "On xinyou, Lun gathered his followers in the Western Garden and said through tears, \"I had no other aim but to destroy the rebels; Xiangdong always believed I contended with him for the throne, and so I am attacked." },
  { zh: "今日欲守則交絕糧儲，欲戰則取笑千載，不容無事受縛，當於下流避之。", literal: "Today, to hold fast cuts off grain and stores; to fight invites mockery for a thousand years; I cannot accept binding without cause—I shall withdraw downriver.", idiomatic: "Today, to hold fast cuts off grain and stores; to fight invites mockery for a thousand years; I cannot accept binding without cause—I shall withdraw downriver." },
  { zh: "」麾下壯士爭請出戰，綸不從，與礩自倉門登舟北出。", literal: "\" His stalwart followers all begged to fight; Lun would not agree and boarded a boat with Li through the granary gate and went north.", idiomatic: "\" His stalwart followers all begged to fight; Lun would not agree and boarded a boat with Li through the granary gate and went north." },
  { zh: "僧辯入據郢州。", literal: "Senbian entered and seized Yingzhou.", idiomatic: "Senbian entered and seized Yingzhou." },
  { zh: "繹以南平王恪為尚書令、開府儀同三司，世子方諸為郢州刺史，王僧辯為領軍將軍。", literal: "Yi made Prince Ke of Nanping Minister of Works and Equal in Honor to the Three Dukes with an Opening Office, Heir Fangzhu Inspector of Yingzhou, and Wang Senbian General of the Palace Guards.", idiomatic: "Yi made Prince Ke of Nanping Minister of Works and Equal in Honor to the Three Dukes with an Opening Office, heir Fangzhu inspector of Yingzhou, and Wang Senbian General of the Palace Guards." },
  { zh: "綸遇鎮東將軍裴之高於道，之高之子畿掠其軍器，綸與左右輕舟奔武昌澗飲寺，僧法馨匿綸於巖穴之下。", literal: "Lun met Garrison-East General Pei Zhigao on the road; Zhigao's son Ji plundered his military gear; Lun with his close followers fled in light boats to Wuchang's Jianyin Temple, where the monk Favin hid Lun in a cave below the cliffs.", idiomatic: "Lun met garrison-east general Pei Zhigao on the road; Zhigao's son Ji plundered his military gear; Lun with his close followers fled in light boats to Wuchang's Jianyin Temple, where the monk Favin hid him in a cave below the cliffs." },
  { zh: "綸長史韋質、司馬姜律等聞綸尚存，馳往迎之，說七柵流民以求糧仗。", literal: "Lun's chief administrator Wei Zhi, chief aide Jiang Lü, and others heard Lun still lived, raced to welcome him, and persuaded the refugee forts of seven palisades to supply grain and arms.", idiomatic: "Lun's chief administrator Wei Zhi, chief aide Jiang Lü, and others heard he still lived, raced to welcome him, and persuaded the refugee forts of seven palisades to supply grain and arms." },
  { zh: "綸出營巴水，流民八九千人附之，稍收散卒，屯於齊昌，遣使請降於齊，齊以綸為梁王。", literal: "Lun encamped on the Ba River; eight or nine thousand refugees attached to him; he gradually gathered scattered soldiers, encamped at Qichang, sent envoys to surrender to Qi, and Qi made Lun Prince of Liang.", idiomatic: "Lun encamped on the Ba River; eight or nine thousand refugees attached to him; he gradually gathered scattered soldiers, encamped at Qichang, sent envoys to surrender to Qi, and Qi made him Prince of Liang." },
  { zh: "湘東王繹改封皇子大款為臨川王，大成為桂陽王，大封為汝南王。", literal: "Prince Yi of Xiangdong changed enfeoffments, making imperial son Dakuan Prince of Linchuan, Dacheng Prince of Guiyang, and Dafeng Prince of Runan.", idiomatic: "Prince Xiao Yi of Xiangdong changed enfeoffments, making imperial son Dakuan Prince of Linchuan, Dacheng Prince of Guiyang, and Dafeng Prince of Runan." },
  { zh: "癸亥，魏軍至潼關。", literal: "On guihai, the Wei army reached Tong Pass.", idiomatic: "On guihai, the Wei army reached Tong Pass." },
  { zh: "庚午，齊主如晉陽，命太子殷居涼風堂監國。", literal: "On gengwu, the Qi emperor went to Jinyang and ordered Crown Prince Yin to dwell in Liangfeng Hall and oversee the state.", idiomatic: "On gengwu, the Qi emperor went to Jinyang and ordered Crown Prince Yin to dwell in Liangfeng Hall and oversee the state." },
  { zh: "南郡王中兵參軍張彪等起兵於若邪山，攻破浙東諸縣，有眾數萬。", literal: "Central Army Adjutant Zhang Biao of the Prince of Nanjun and others raised troops on Mount Ruoye, stormed the eastern Zhe counties, and had a force of tens of thousands.", idiomatic: "Central army adjutant Zhang Biao of the Prince of Nanjun and others raised troops on Mount Ruoye, stormed the eastern Zhe counties, and mustered tens of thousands." },
  { zh: "吳郡人陸令公等說太守南海王大臨往依之。", literal: "Lu Linggong of Wu commandery and others urged Administrator Prince Dalin of Nanhai to go and rely on him.", idiomatic: "Lu Linggong of Wu commandery and others urged administrator Prince Dalin of Nanhai to join him." },
  { zh: "大臨曰：「彪若成功，不資我力；", literal: "Dalin said, \"If Biao succeeds, he will not need my strength.", idiomatic: "Dalin said, \"If Biao succeeds, he will not need my strength." },
  { zh: "如其橈敗，以我自解。", literal: "If he is broken and defeated, he will use me to excuse himself.", idiomatic: "If he is broken and defeated, he will use me to excuse himself." },
  { zh: "不可往也。", literal: "I must not go.", idiomatic: "I must not go." },
  { zh: "任約進寇西陽、武昌。", literal: "Ren Yue advanced to raid Xiyang and Wuchang.", idiomatic: "Ren Yue advanced to raid Xiyang and Wuchang." },
  { zh: "初，寧州刺史彭城徐文盛募兵數萬人討侯景，湘東王繹以為秦州刺史，使將兵東下，與約遇於武昌。", literal: "Earlier, Ningzhou Inspector Xu Wensheng of Pengcheng raised tens of thousands of men to attack Hou Jing; Prince Yi of Xiangdong made him Inspector of Qinzhou and had him lead troops east; he met Yue at Wuchang.", idiomatic: "Earlier, Ningzhou inspector Xu Wensheng of Pengcheng raised tens of thousands to attack Hou Jing; Prince Xiao Yi of Xiangdong made him inspector of Qinzhou and had him lead troops east; he met Yue at Wuchang." },
  { zh: "繹以廬陵王應為江州刺史，以文盛為長史行府州事，督諸將拒之。", literal: "Yi made Prince Ying of Luling Inspector of Jiangzhou, made Wensheng Chief Administrator acting for headquarters and province, and had him supervise the generals in resistance.", idiomatic: "Yi made Prince Ying of Luling inspector of Jiangzhou, made Wensheng chief administrator acting for headquarters and province, and had him supervise the generals in resistance." },
  { zh: "應，續之子也。", literal: "Ying was Xu's son.", idiomatic: "Ying was Xu's son." },
  { zh: "邵陵王綸引齊兵未至，移營馬柵，距西陽八十里，任約聞之，遣儀同叱羅子通等將鐵騎二百襲之，綸不為備，策馬亡走。", literal: "Prince Lun of Shaoling had drawn Qi troops but they had not arrived; he moved camp to Mazha, eighty li from Xiyang; Ren Yue heard of it and sent Equal in Honor Chiluo Zitong and others with two hundred iron cavalry to surprise him; Lun made no preparations and fled on horseback.", idiomatic: "Prince Lun of Shaoling had drawn Qi troops but they had not arrived; he moved camp to Mazha, eighty li from Xiyang; Ren Yue heard and sent Chiluo Zitong, Equal in Honor, and others with two hundred iron cavalry to surprise him; Lun was caught unawares and fled on horseback." },
  { zh: "時湘東王繹亦與齊連和，故齊人觀望，不助綸。", literal: "At the time Prince Yi of Xiangdong was also allied with Qi, so the Qi men watched and did not aid Lun.", idiomatic: "At the time Prince Xiao Yi of Xiangdong was also allied with Qi, so the Qi men held back and did not aid Lun." },
  { zh: "定州刺史田祖龍迎綸，綸以祖龍為繹所厚，懼為所執，復歸齊昌。", literal: "Dingzhou Inspector Tian Zulong welcomed Lun; Lun, because Zulong was favored by Yi, feared he would be seized and returned to Qichang.", idiomatic: "Dingzhou inspector Tian Zulong welcomed Lun; Lun, because Zulong was favored by Yi, feared seizure and returned to Qichang." },
  { zh: "行至汝南，魏所署汝南城主李素，綸之故吏也，開城納之，任約遂據西陽、武昌。", literal: "Reaching Runan, Li Su, city chief of Runan appointed by Wei and Lun's former clerk, opened the city and received him; Ren Yue then held Xiyang and Wuchang.", idiomatic: "Reaching Runan, Li Su, city chief of Runan appointed by Wei and Lun's former clerk, opened the city and received him; Ren Yue then held Xiyang and Wuchang." },
  { zh: "裴之高帥子弟部曲千餘人至夏首，湘東王繹召之，以為新興、永守二郡太守。", literal: "Pei Zhigao led more than a thousand men of his clan retainers to Xiashou; Prince Yi of Xiangdong summoned him and made him Administrator of the two commanderies of Xinxing and Yongshou.", idiomatic: "Pei Zhigao led more than a thousand clan retainers to Xiashou; Prince Xiao Yi of Xiangdong summoned him and made him administrator of Xinxing and Yongshou." },
  { zh: "又以南平王恪為武州刺史，鎮武陵。", literal: "He also made Prince Ke of Nanping Inspector of Wuzhou and garrisoned Wuling.", idiomatic: "He also made Prince Ke of Nanping inspector of Wuzhou and garrisoned Wuling." },
  { zh: "初，邵陵王綸以衡陽王獻為齊州刺史，鎮齊昌；", literal: "Earlier, Prince Lun of Shaoling had made Prince Xian of Hengyang Inspector of Qizhou and garrisoned Qichang.", idiomatic: "Earlier, Prince Lun of Shaoling had made Prince Xian of Hengyang inspector of Qizhou and garrisoned Qichang." },
  { zh: "任約擊擒之，送建康，殺之。", literal: "Ren Yue struck, captured him, sent him to Jiankang, and killed him.", idiomatic: "Ren Yue struck, captured him, sent him to Jiankang, and killed him." },
  { zh: "獻，暢之孫也。", literal: "Xian was Chang's grandson.", idiomatic: "Xian was Chang's grandson." },
  { zh: "乙亥，進侯景位相國，封二十郡，為漢王，加殊禮。", literal: "On yihai, Hou Jing was advanced to Chancellor of State, enfeoffed with twenty commanderies as Prince of Han, and granted extraordinary honors.", idiomatic: "On yihai, Hou Jing was advanced to Chancellor of State, enfeoffed with twenty commanderies as Prince of Han, and granted extraordinary honors." },
  { zh: "岳陽王察還襄陽。", literal: "Prince Cha of Yueyang returned to Xiangyang.", idiomatic: "Prince Cha of Yueyang returned to Xiangyang." },
  { zh: "黎州民攻刺史張賁，賁棄城走。", literal: "The people of Lizhou attacked Inspector Zhang Ben; Ben abandoned the city and fled.", idiomatic: "The people of Lizhou attacked inspector Zhang Ben; Ben abandoned the city and fled." },
  { zh: "州民引氐酋北益州刺史楊法琛據黎州，命王、賈二姓詣武陵王紀請法琛為刺史。", literal: "The provincials brought in the Di chieftain Yang Fachen, Northern Yi Inspector, to hold Lizhou, and ordered the Wang and Jia clans to go to Prince Ji of Wuling and ask that Fachen be made inspector.", idiomatic: "The provincials brought in Di chieftain Yang Fachen, Northern Yi inspector, to hold Lizhou, and sent the Wang and Jia clans to Prince Ji of Wuling to ask that Fachen be made inspector." },
  { zh: "紀深責之，囚法琛質子崇顒、崇虎。", literal: "Ji rebuked them severely and imprisoned Fachen's hostage sons Chongyan and Chonghu.", idiomatic: "Ji rebuked them severely and imprisoned Fachen's hostage sons Chongyan and Chonghu." },
  { zh: "冬，十月，丁丑朔，法琛遣使附魏。", literal: "In winter, the tenth month, on the first day dingchou, Fachen sent envoys to submit to Wei.", idiomatic: "In winter, the tenth month, on the first day dingchou, Fachen sent envoys to submit to Wei." },
  { zh: "己卯，齊主至晉陽宮。", literal: "On jimao, the Qi emperor reached Jinyang Palace.", idiomatic: "On jimao, the Qi emperor reached Jinyang Palace." },
  { zh: "廣武王長弼與并州刺史段韶不協，齊主將如晉陽，長弼言於帝曰：「韶擁強兵在彼，恐不知人意，豈可徑往投之！", literal: "Prince Changbi of Guangwu was at odds with Bingzhou Inspector Duan Shao; as the Qi emperor was about to go to Jinyang, Changbi said to him, \"Shao holds strong troops there and may not know men's hearts—how can you go straight and throw yourself upon him!", idiomatic: "Prince Changbi of Guangwu was at odds with Bingzhou inspector Duan Shao; as the Qi emperor was about to go to Jinyang, Changbi said, \"Shao holds strong troops there and may not read men's hearts—how can you go straight and throw yourself upon him!" },
  { zh: "」帝不聽。", literal: "\" The emperor would not listen.", idiomatic: "\" The emperor would not listen." },
  { zh: "既至，以長弼語告之，曰：「如君忠誠，人猶有讒，況其餘乎！", literal: "Once he arrived, he told Shao Changbi's words and said, \"With loyalty like yours, men still slander you—how much more the rest!", idiomatic: "Once he arrived, he told Shao what Changbi had said: \"With loyalty like yours, men still slander you—how much more the rest!" },
  { zh: "」長弼，永樂之弟也。", literal: "\" Changbi was Yongle's younger brother.", idiomatic: "\" Changbi was Yongle's younger brother." },
  { zh: "乙酉，以特進元韶為尚書左僕射，段韶為右僕射。", literal: "On yiyou, he made Special Advance Yuan Shao Left Vice Minister of Works and Duan Shao Right Vice Minister.", idiomatic: "On yiyou, he made Special Advance Yuan Shao Left Vice Minister of Works and Duan Shao Right Vice Minister." },
  { zh: "乙未，侯景自加宇宙大將軍、都督六合諸軍事，以詔文呈上。", literal: "On yiwei, Hou Jing on his own authority added Grand General of the Cosmos and Commander of All Military Affairs in the Six Directions, and presented the edict text to the emperor.", idiomatic: "On yiwei, Hou Jing on his own authority added Grand General of the Cosmos and Commander of All Military Affairs in the Six Directions, and presented the edict text to the emperor." },
  { zh: "上驚曰：「將軍乃有宇宙之號乎！", literal: "The emperor was startled and said, \"General, you would even take a title of the cosmos!", idiomatic: "The emperor was startled: \"General, you would even take a title of the cosmos!" },
  { zh: "立皇子大鈞為西陽王，大威為武寧王，大球為建安王，大昕為義安王，大摯為綏建王，大圜為樂梁王。", literal: "He made imperial sons Dajun Prince of Xiyang, Dawei Prince of Wuning, Daqiu Prince of Jian'an, Daxin Prince of Yi'an, Dazhi Prince of Suijian, and Dayuan Prince of Leliang.", idiomatic: "He made imperial sons Dajun Prince of Xiyang, Dawei Prince of Wuning, Daqiu Prince of Jian'an, Daxin Prince of Yi'an, Dazhi Prince of Suijian, and Dayuan Prince of Leliang." },
  { zh: "齊東徐州刺史行台辛術鎮下邳。", literal: "Eastern Xuzhou Inspector and Mobile Headquarters Xin Shu of Qi garrisoned Xiapi.", idiomatic: "Eastern Xuzhou inspector and mobile headquarters Xin Shu of Qi garrisoned Xiapi." },
  { zh: "十一月，侯景征租入建康，術帥眾度淮斷之，燒其谷百萬石，遂圍陽平，景行台郭元建引兵救之。", literal: "In the eleventh month, Hou Jing levied grain rents into Jiankang; Shu led his force across the Huai to cut them off, burned a million shi of grain, then besieged Yangping; Jing's mobile headquarters Guo Yuanjian led troops to rescue it.", idiomatic: "In the eleventh month, Hou Jing levied grain rents into Jiankang; Shu led his force across the Huai to cut them off, burned a million shi of grain, then besieged Yangping; Hou Jing's mobile headquarters Guo Yuanjian led troops to rescue it." },
  { zh: "壬戌，術略三千餘家，還下邳。", literal: "On renxu, Shu raided more than three thousand households and returned to Xiapi.", idiomatic: "On renxu, Shu raided more than three thousand households and returned to Xiapi." },
  { zh: "武陵王紀帥諸軍發成都，湘東王繹遣使以書止之曰：「蜀人勇悍，易動難安，弟可鎮之，吾自當滅賊。", literal: "Prince Ji of Wuling led the armies out from Chengdu; Prince Yi of Xiangdong sent envoys with a letter stopping him, saying, \"The men of Shu are fierce and hard to settle once stirred; younger brother, you can hold them—I myself will destroy the rebels.", idiomatic: "Prince Ji of Wuling led the armies out from Chengdu; Prince Xiao Yi of Xiangdong sent envoys with a letter stopping him: \"The men of Shu are fierce and hard to settle once stirred; younger brother, hold them—I myself will destroy the rebels." },
  { zh: "」又別紙云：「地擬孫、劉，各安境界；", literal: "\" On a separate sheet he wrote, \"Our lands may be compared to Sun and Liu—each keeps his border.", idiomatic: "\" On a separate sheet he wrote, \"Our lands may be compared to Sun and Liu—each keeps his border." },
  { zh: "情深魯、衛，書信恆通。", literal: "Our bond is deep as Lu and Wei—letters should always pass.", idiomatic: "Our bond is deep as Lu and Wei—letters should always pass." },
  { zh: "甲子，南平王恪帥文武拜箋推湘東王繹為相國，總百揆；", literal: "On jiazi, Prince Ke of Nanping led civil and military officials in a memorial urging Prince Yi of Xiangdong as Chancellor of State to oversee the hundred duties.", idiomatic: "On jiazi, Prince Ke of Nanping led civil and military officials in a memorial urging Prince Xiao Yi of Xiangdong as Chancellor of State to oversee the hundred duties." },
  { zh: "繹不許。", literal: "Yi refused.", idiomatic: "Yi refused." },
  { zh: "魏丞相泰自弘農為橋，濟河，至建州。", literal: "Wei Chancellor Tai built a bridge from Hongnong, crossed the river, and reached Jianzhou.", idiomatic: "Chancellor Yuwen Tai built a bridge from Hongnong, crossed the river, and reached Jianzhou." },
  { zh: "丙寅，齊主自將出頓東城。", literal: "On bingyin, the Qi emperor personally led the army out and encamped at East City.", idiomatic: "On bingyin, the Qi emperor personally led the army out and encamped at East City." },
  { zh: "泰聞其軍容嚴盛，歎曰：「高歡不死矣！", literal: "Tai heard his army's bearing was stern and grand and sighed, \"Gao Huan is not dead after all!", idiomatic: "Tai heard his army's bearing was stern and grand and sighed, \"Gao Huan is not dead after all!" },
  { zh: "」會久雨，自秋及冬，魏軍畜產多死，乃自蒲阪還。", literal: "\" It happened that long rains lasted from autumn into winter; many of the Wei army's livestock died, and they returned from Puban.", idiomatic: "\" Long rains lasted from autumn into winter; much of the Wei army's livestock died, and they returned from Puban." },
  { zh: "於是河南自洛陽，河北自平陽已東，皆入於齊。", literal: "Thereupon south of the river from Luoyang and north of the river from east of Pingyang all entered Qi.", idiomatic: "Thereupon south of the river from Luoyang and north of the river from east of Pingyang all fell to Qi." },
  { zh: "丁卯，徐文盛軍貝磯，任約帥水軍逆戰，文盛大破之，斬叱羅子通、趙威方，仍進軍大舉口。", literal: "On dingmao, Xu Wensheng's army was at Beiji; Ren Yue led the water force to meet in battle; Wensheng routed him, beheaded Chiluo Zitong and Zhao Weifang, and advanced to Dajukou.", idiomatic: "On dingmao, Xu Wensheng's army was at Beiji; Ren Yue led the water force to meet him; Wensheng routed him, beheaded Chiluo Zitong and Zhao Weifang, and advanced to Dajukou." },
  { zh: "侯景遣宋子仙等將兵二萬助約，以約守西陽，久不能進，自出屯晉熙。", literal: "Hou Jing sent Song Zixian and others with twenty thousand troops to aid Yue, had Yue hold Xiyang, and when he could not advance for long, went out himself to encamp at Jinxi.", idiomatic: "Hou Jing sent Song Zixian and others with twenty thousand troops to aid Yue, had Yue hold Xiyang, and when progress stalled, went out himself to encamp at Jinxi." },
  { zh: "南康王會理以建康空虛，與太子左衛將軍柳敬禮、西鄉侯勸、東鄉侯勉謀起兵誅王偉。", literal: "Prince Huili of Nankang, because Jiankang was empty, with Crown Prince Left Guard General Liu Jingli, Marquis Quan of Xixiang, and Marquis Mian of Dongxiang plotted to raise troops and kill Wang Wei.", idiomatic: "Prince Huili of Nankang, because Jiankang was empty, with crown prince left guard general Liu Jingli, Marquis Quan of Xixiang, and Marquis Mian of Dongxiang plotted to raise troops and kill Wang Wei." },
  { zh: "安樂侯乂理出奔長蘆，集眾得千餘人。", literal: "Marquis Yili of Anle fled to Changlu, gathered followers, and had more than a thousand men.", idiomatic: "Marquis Yili of Anle fled to Changlu, gathered followers, and mustered more than a thousand men." },
  { zh: "建安侯賁、中宿世子子邕知其謀，以告偉。", literal: "Marquis Ben of Jian'an and Heir Ziyong of Zhongsu learned of the plot and reported it to Wei.", idiomatic: "Marquis Ben of Jian'an and heir Ziyong of Zhongsu learned of the plot and reported it to Wei." },
  { zh: "偉收會理、敬禮、勸、勉及會理弟祁陽侯通理，俱殺之。", literal: "Wei seized Huili, Jingli, Quan, Mian, and Huili's younger brother Marquis Tongli of Qiyang, and killed them all.", idiomatic: "Wei seized Huili, Jingli, Quan, Mian, and Huili's younger brother Marquis Tongli of Qiyang, and killed them all." },
  { zh: "乂理為左右所殺。", literal: "Yili was killed by his own followers.", idiomatic: "Yili was killed by his own followers." },
  { zh: "錢塘褚冕，以會理故舊，捶掠千計，終無異言。", literal: "Chu Mian of Qiantang, because of old ties with Huili, was beaten more than a thousand strokes yet to the end spoke no different word.", idiomatic: "Chu Mian of Qiantang, because of old ties with Huili, was beaten more than a thousand strokes yet never spoke a different word." },
  { zh: "會理隔壁謂之曰：「褚郎，卿豈不為我致此？", literal: "Huili in the next cell said to him, \"Master Chu, did you not bring this upon me?", idiomatic: "Huili in the next cell said to him, \"Master Chu, did you not bring this upon me?" },
  { zh: "卿雖忍死明我，我心實欲殺賊！", literal: "Though you endure death to clear me, in my heart I truly wished to kill the rebels!", idiomatic: "Though you endure death to clear me, in my heart I truly wished to kill the rebels!" },
  { zh: "」冕竟不服，景乃宥之。", literal: "\" Mian to the end would not submit; Jing then pardoned him.", idiomatic: "\" Mian to the end would not submit; Hou Jing then pardoned him." },
  { zh: "勸，昺之子；", literal: "Quan was Bing's son.", idiomatic: "Quan was Bing's son." },
  { zh: "賁，正德之弟子；", literal: "Ben was Zhengde's younger brother's son.", idiomatic: "Ben was Zhengde's nephew." },
  { zh: "子邕，憺之孫也。", literal: "Ziyong was Dan's grandson.", idiomatic: "Ziyong was Dan's grandson." },
  { zh: "帝自即位以來，景防衛甚嚴，外人莫得進見，唯武林侯諮及僕射王克、舍人殷不害，並以文弱得出入臥內，帝與之講論而已。", literal: "Since the emperor took the throne, Jing's guard had been very strict and outsiders could not gain audience; only Marquis Zi of Wulin and Vice Minister Wang Ke and Attendant Yin Buhai, all frail in manner, could enter the sleeping quarters, and the emperor discussed texts with them—that was all.", idiomatic: "Since the emperor took the throne, Hou Jing's guard had been very strict and outsiders could not gain audience; only Marquis Zi of Wulin, vice minister Wang Ke, and attendant Yin Buhai, all frail in manner, could enter the sleeping quarters, and the emperor discussed texts with them—that was all." },
  { zh: "及會理死，克、不害懼禍，稍自疏。", literal: "When Huili died, Ke and Buhai feared disaster and gradually kept their distance.", idiomatic: "When Huili died, Ke and Buhai feared disaster and gradually kept their distance." },
  { zh: "咨獨不離帝，朝請無絕；", literal: "Zi alone did not leave the emperor; morning audiences never ceased.", idiomatic: "Zi alone did not leave the emperor; morning audiences never ceased." },
  { zh: "景惡之，使其仇人刁戍刺殺咨於廣莫門外。", literal: "Jing hated this and had his enemy Diao Shu assassinate Zi outside the Guangmo Gate.", idiomatic: "Hou Jing hated this and had his enemy Diao Shu assassinate Zi outside the Guangmo Gate." },
  { zh: "帝之即位也，景與帝登重雲殿，禮佛為誓云：「自今君臣兩無猜貳，臣固不負陛下，陛下亦不得負臣！", literal: "When the emperor took the throne, Jing and the emperor ascended Chongyun Hall, worshipped the Buddha, and swore, saying, \"From now on lord and minister shall harbor no mutual suspicion; your servant surely will not fail Your Majesty, and Your Majesty must not fail your servant!", idiomatic: "When the emperor took the throne, Hou Jing and the emperor ascended Chongyun Hall, worshipped the Buddha, and swore: \"From now on lord and minister shall harbor no mutual suspicion; your servant will not fail Your Majesty, and Your Majesty must not fail your servant!" },
  { zh: "」及會理謀洩，景疑帝知之，故殺咨。", literal: "\" When Huili's plot leaked, Jing suspected the emperor knew and therefore killed Zi.", idiomatic: "\" When Huili's plot leaked, Hou Jing suspected the emperor knew and therefore killed Zi." },
  { zh: "帝自知不久，指所居殿謂殷不害曰：「龐涓當死此下。", literal: "The emperor knew he would not last long, pointed at the hall where he dwelt, and told Yin Buhai, \"Pang Juan ought to die beneath this.", idiomatic: "The emperor knew he would not last long, pointed at the hall where he dwelt, and told Yin Buhai, \"Pang Juan ought to die beneath this." },
  { zh: "景自帥眾討楊白華於宣城，白華力屈而降，景以其北人，全之，以為左民尚書，誅其兄子彬以報來亮之怨。", literal: "Jing himself led the host to attack Yang Baihua at Xuancheng; Baihua, strength exhausted, surrendered; Jing, because he was a northerner, spared him and made him Minister of the Left People, but executed his elder brother's son Bin to repay Lai Liang's grudge.", idiomatic: "Hou Jing himself led the host to attack Yang Baihua at Xuancheng; Baihua, strength exhausted, surrendered; Hou Jing, because he was a northerner, spared him and made him Minister of the Left People, but executed his elder brother's son Bin to repay Lai Liang's grudge." },
  { zh: "十二月，丙子朔，景封建安侯賁為竟陵王，中宿世子子邕為隨王，仍賜姓侯氏。", literal: "In the twelfth month, on the first day bingzi, Jing enfeoffed Marquis Ben of Jian'an as Prince of Jingling and Heir Ziyong of Zhongsu as Prince of Sui, and further granted the surname Hou.", idiomatic: "In the twelfth month, on the first day bingzi, Hou Jing enfeoffed Marquis Ben of Jian'an as Prince of Jingling and heir Ziyong of Zhongsu as Prince of Sui, and further granted the surname Hou." },
  { zh: "辛丑，齊主還鄴。", literal: "On xinchou, the Qi emperor returned to Ye.", idiomatic: "On xinchou, the Qi emperor returned to Ye." },
  { zh: "邵陵王綸在汝南，修城池，集士卒，將圖安陸。", literal: "Prince Lun of Shaoling was at Runan, repaired walls and moats, gathered soldiers, and intended to take Anlu.", idiomatic: "Prince Lun of Shaoling was at Runan, repaired walls and moats, gathered soldiers, and intended to take Anlu." },
  { zh: "魏安州刺史馬祐以告丞相泰，泰遣楊忠將萬人救安陸。", literal: "Wei Anzhou Inspector Ma You reported to Chancellor Tai; Tai sent Yang Zhong with ten thousand men to rescue Anlu.", idiomatic: "Wei Anzhou inspector Ma You reported to Chancellor Tai; Tai sent Yang Zhong with ten thousand men to rescue Anlu." },
  { zh: "武陵王紀遣潼州刺史楊乾運、南梁州刺史譙淹合兵二萬討楊法琛，法琛發兵據劍閣以拒之。", literal: "Prince Ji of Wuling sent Tongzhou Inspector Yang Qianyun and Nanliangzhou Inspector Qiao Yan with a combined force of twenty thousand to attack Yang Fachen; Fachen raised troops and held Jiange Pass to resist.", idiomatic: "Prince Ji of Wuling sent Tongzhou inspector Yang Qianyun and Nanliangzhou inspector Qiao Yan with twenty thousand men to attack Yang Fachen; Fachen raised troops and held Jiange Pass to resist." },
  { zh: "侯景還建康。", literal: "Hou Jing returned to Jiankang.", idiomatic: "Hou Jing returned to Jiankang." },
  { zh: "初，魏敬宗以爾朱榮為柱國大將軍，位在丞相上；", literal: "Earlier, Emperor Jingzong of Wei had made Erzhu Rong Grand General of the Pillars, rank above the chancellor.", idiomatic: "Earlier, Emperor Jingzong of Wei had made Erzhu Rong Grand General of the Pillars, rank above the chancellor." },
  { zh: "榮敗，此官遂廢。", literal: "When Rong was defeated, the office was then abolished.", idiomatic: "When Rong was defeated, the office was abolished." },
  { zh: "大統三年，文帝復以丞相泰為之。", literal: "In the third year of Datong, Emperor Wen again made Chancellor Tai holder of it.", idiomatic: "In the third year of Datong, Emperor Wen again made Chancellor Tai holder of it." },
  { zh: "其後功參佐命，望實俱重者，亦居此官，凡八人，曰安定公宇文泰，廣陵王欣，趙郡公李弼，隴西公李虎，河內公獨孤信，南陽公趙貴，常山公於謹，彭城公侯莫陳崇，謂之八柱國。", literal: "Thereafter those whose merit shared in founding the mandate and whose repute and substance were both weighty also held this office—eight in all: Duke of Anding Yuwen Tai, Prince Xin of Guangling, Duke of Zhaojun Li Bi, Duke of Longxi Li Hu, Duke of Henei Dugu Xin, Duke of Nanyang Zhao Gui, Duke of Changshan Yu Jin, and Duke of Pengcheng Hou Mo Chen Chong—called the Eight Pillars.", idiomatic: "Thereafter those whose merit shared in founding the mandate and whose repute and substance were both weighty also held this office—eight in all: Duke of Anding Yuwen Tai, Prince Xin of Guangling, Duke of Zhaojun Li Bi, Duke of Longxi Li Hu, Duke of Henei Dugu Xin, Duke of Nanyang Zhao Gui, Duke of Changshan Yu Jin, and Duke of Pengcheng Hou Mo Chen Chong—the Eight Pillars." },
  { zh: "泰始籍民之才力者為府兵，身租庸調，一切蠲之，以農隙講閱戰陳，馬畜糧備，六家供之；", literal: "Tai first registered men of talent and strength among the people as garrison soldiers, exempting them entirely from body-tax, corvée, and cloth levies; in the gaps of farming they drilled battle formations; horses, livestock, grain, and stores were supplied by six households.", idiomatic: "Tai first registered men of talent and strength as garrison soldiers, exempting them entirely from body-tax, corvée, and cloth levies; in the gaps of farming they drilled battle formations; horses, livestock, grain, and stores were supplied by six households." },
  { zh: "合為百府，每府一郎將主之，分屬二十四軍。", literal: "They were combined into a hundred garrisons, each garrison with one commandant in charge, divided among twenty-four armies.", idiomatic: "They were combined into a hundred garrisons, each with one commandant in charge, divided among twenty-four armies." },
  { zh: "泰任總百揆，督中外諸軍；", literal: "Tai held overall charge of the hundred duties and supervised all forces inside and outside.", idiomatic: "Tai held overall charge of the hundred duties and supervised all forces inside and outside." },
  { zh: "欣以宗室宿望，從容禁闥而已。", literal: "Xin, by imperial clan and long-standing repute, merely moved at ease within the inner gates.", idiomatic: "Xin, by imperial clan and long-standing repute, merely moved at ease within the inner gates." },
  { zh: "餘六人各督二大將軍，凡十二大將軍，每大將軍各統開府二人，開府各領一軍。", literal: "The remaining six each supervised two grand generals—twelve grand generals in all; each grand general in turn commanded two opening offices, and each opening office led one army.", idiomatic: "The remaining six each supervised two grand generals—twelve in all; each grand general commanded two opening offices, and each opening office led one army." },
  { zh: "是後功臣位至柱國大將軍、開府儀同三司、儀同三司者甚眾，率為散官，無所統御，雖有繼掌其事者，聞望皆出諸公之下雲。", literal: "After this, meritorious men reaching Grand General of the Pillars, Opening Office Equal in Honor to the Three Dukes, or Equal in Honor to the Three Dukes were very many; mostly they were nominal offices with nothing to command; even when successors held the posts, their fame and standing all fell below these lords.", idiomatic: "After this, meritorious men reaching Grand General of the Pillars, Opening Office Equal in Honor to the Three Dukes, or Equal in Honor to the Three Dukes were very many; mostly they were nominal offices with nothing to command; even when successors held the posts, their fame and standing all fell below these lords." },
  { zh: "齊主命散騎侍郎宋景業造《天保歷》，行之。", literal: "The Qi emperor ordered Direct Attendant Song Jingye to compose the Tianbao Calendar, and it was put in use.", idiomatic: "The Qi emperor ordered direct attendant Song Jingye to compose the Tianbao Calendar, and it was put in use." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
